  },
  'After-Ignorance': {
    'id': 1220,
    'definition': '<b>\'AFTER-IGNORANCE</b>, <i>n.</i> Subsequent ignorance.',
  },
  'After-King': {
    'id': 1221,
    'definition': '<b>\'AFTER-KING</b>, <i>n.</i> A succeeding king.',
  },
  'After-Life': {
    'id': 1222,
    'definition': '<b>\'AFTER-LIFE</b>, <i>n.</i><br><br>1. Future life or the life after this.<br><br>2. A later period of life; subsequent life.',
  },
  'After-Liver': {
