  'Bandle': {
    'id': 4730,
    'definition': '<b>BAN\'DLE</b>, <i>n.</i> An Irish measure of two feet in length.',
  },
  'Bandlet': {
    'id': 4731,
    'definition': '<b>BAND\'LET<br><br>BAN\'DOG</b>, <i>n,</i> A large species of dog.',
