  'Batz': {
    'id': 5070,
    'definition': '<b>BATZ</b>, <i>n.</i> A small copper coin with a mixture of silver,current in some parts of Germany and Switzerland.',
  },
  'Baubee': {
    'id': 5071,
    'definition': '<b>BAUBEE\'</b>, <i>n.</i> In Scotland the North of England, a half penny.',
