  'Bestud': {
    'id': 5754,
    'definition': '<b>BESTUD\'</b>, <i>v.t.</i> [be and stud.] To set with studs; to adorn with bosses; as, to bestud with stars.',
  },
  'Bestudded': {
    'id': 5755,
    'definition': '<b>BESTUD\'DED</b>,pp. Adorned with studs.',
