  'Bloodless': {
    'id': 6330,
    'definition': '<b>BLOOD\'LESS</b>, <i>a.</i> Without blood; dead.<br><br>1. Without shedding of blood or slaughter; as a bloodless victory.<br><br>2. Without spirit or activity.',
  },
  'Bloodletting': {
    'id': 6331,
    'definition': '<b>BLOOD\'LETTING</b>, <i>n.</i> [blood and let.] The act of letting blood, or bleeding by opening a vein.',
