  'Boud': {
    'id': 6735,
    'definition': '<b>BOUD</b>, <i>n.</i> An insect that breeds in malt or other grain; called also a weevil.',
  },
  'Bouge': {
    'id': 6736,
    'definition': '<b>BOUGE</b>, <i>v.i.</i> booj. To swell out. [Little used.]<br><br><b>BOUGE</b>, <i>n.</i> Provisions. [Not in use.]',
