  'Brabantine': {
    'id': 6837,
    'definition': '<b>BRABANT\'INE</b>, <i>a.</i> Pertaining to Brabant, a province of the Netherlands, of which Brussels is the capital.',
  },
  'Brabble': {
    'id': 6838,
    'definition': '<b>BRAB\'BLE</b>, <i>n.</i> A broil; a clamorous contest; a wrangle.<br><br><b>BRAB\'BLE</b>, <i>v.i.</i> To clamor; to contest noisily.',
  },
  'Brabbler': {
    'id': 6839,
    'definition': '<b>BRAB\'BLER</b>, <i>n.</i> A clamorous, quarrelsome, noisy fellow; a wrangler.',
