  'Broad-Brimmed': {
    'id': 7178,
    'definition': '<b>BROAD-BRIMMED</b>, <i>a.</i> [broad and brim.] Having a broad brim.',
  },
  'Broad-Cast': {
    'id': 7179,
    'definition': '<b>BROAD-CAST</b>, <i>n.</i> [broad and cast.] Among farmers, a casting or throwing seed from the hand for dispersion in sowing.<br><br><b>BROAD-CAST</b>, <i>adv.</i> By scattering or throwing at large from the hand; as, to sow broad-cast.<br><br><b>BROAD-CAST</b>, <i>a.</i> Cast or dispersed upon the ground with the hand, as seed in sowing; opposed to planting in hills or rows.',
  },
  'Broad-Cloth': {
    'id': 7180,
    'definition': '<b>BROAD-CLOTH</b>, <i>n.</i> A species of woolen cloth, so called from its breadth.',
  },
  'Broad-Eyed': {
    'id': 7181,
    'definition': '<b>BROAD-EYED</b>, <i>a.</i> [broad and eye.] Having a wide view or survey; as broad-eyed day.',
