    'definition': '<b>BROAD-LEAVED,<br><br>BROAD-PIECE</b>, <i>n.</i> [broad and piece.] A piece of gold coin broader than a guinea.',
  },
  'Broad-Seal': {
    'id': 7186,
    'definition': '<b>BROAD-SEAL</b>, <i>n.</i> The great seal of England; as a verb,not used.',
