  'Caballer': {
    'id': 7656,
    'definition': '<b>CABALLER</b>, <i>n.</i> One who unites with others in close designs to effect an object by intrigue; one who cabals.',
  },
  'Caballine': {
    'id': 7657,
    'definition': '<b>CABALLINE</b>, <i>a.</i> Pertaining to a horse; as caballine aloes, so called from its being given to horses as a purge.',
  },
  'Caballing': {
    'id': 7658,
    'definition': '<b>CABALLING</b>, <i>ppr.</i> Uniting in a cabal; intriguing in a small party.',
