  'Carle': {
    'id': 8265,
    'definition': '<b>CARLE</b>, <i>n.</i><br><br>1. A rude, rustic, rough, brutal man.<br><br>2. A kind of hemp.<br><br><b>CARLE</b>, <i>v.i.</i> To act like a churl.',
  },
  'Carline': {
    'id': 8266,
    'definition': '<b>CARLINE, OR CAROLINE</b>, <i>n.</i> A silver coin in Naples.',
