  'Chamber-Maid': {
    'id': 8946,
    'definition': '<b>CHAMBER-MAID,<br><br>CHAMBER-MAID</b>, <i>n.</i> A woman who has the care of chambers, making the beds, and cleaning the rooms, or who dresses a lady and waits upon her in her apartment.',
  },
  'Chamber-Pot': {
    'id': 8947,
    'definition': '<b>CHAMBER-POT</b>, <i>n.</i> A vessel used in bedrooms.',
