  'Chanting': {
    'id': 9009,
    'definition': '<b>CHANTING</b>, <i>ppr.</i> Singing; uttering a melodious voice; repeating words with a singing voice.<br><br><b>CHANTING</b>, <i>n.</i> The act of singing, or uttering with a song.',
  },
  'Chantress': {
    'id': 9010,
    'definition': '<b>CHANTRESS</b>, <i>n.</i> A female singer.',
