  'Chilli': {
    'id': 9311,
    'definition': '<b>CHILLI</b>, <i>n.</i> A Mexican plant, Guinea pepper.',
  },
  'Chilliness': {
    'id': 9312,
    'definition': '<b>CHILLINESS</b>, <i>n.</i><br><br>1. A sensation of shivering; rigors.<br><br>2. A moderate degree of coldness; as the chilliness of the air, which tends to cause a shivering.',
  },
  'Chilling': {
