  'Chlorate': {
    'id': 9392,
    'definition': '<b>CHLORATE</b>, <i>n.</i> [See <a href="dict://chlorine">chlorine</a>.] A compound of chloric acid with a salifiable base.',
  },
  'Chloric': {
    'id': 9393,
    'definition': '<b>CHLORIC</b>, <i>a.</i> Pertaining to chlorine, or obtained from it; as chloric acid.',
