  'Circumfusion': {
    'id': 9696,
    'definition': '<b>CIRCUMFUSION</b>, <i>n.</i> [See <a href="dict://Circumfuse">Circumfuse</a>.] The act of pouring or spreading round; the state of being poured round.',
  },
  'Circumgestation': {
    'id': 9697,
    'definition': '<b>CIRCUMGESTATION</b>, <i>n.</i> A carrying about.',
  },
  'Circumgyrate': {
    'id': 9698,
    'definition': '<b>CIRCUMGYRATE,<br><br>CIRCUMGYRATION</b>, <i>n.</i> The act of turning, rolling or whirling round; the turning of a limb in its socket.',
  },
  'Circumgyre': {
