  'Circumjacent': {
    'id': 9700,
    'definition': '<b>CIRCUMJACENT</b>, <i>a.</i> Lying round; bordering on every side.',
  },
  'Circumligation': {
    'id': 9701,
    'definition': '<b>CIRCUMLIGATION</b>, <i>n.</i> The act of binding round; the bond with which any thing is encompassed.',
  },
  'Circumlocution': {
    'id': 9702,
    'definition': '<b>CIRCUMLOCUTION</b>, <i>n.</i> A circuit or compass of words; a periphrase; the use of a number of words to express an idea, when a suitable term is not at hand, or when a speaker chooses to avoid the use of a single term, either from delicacy or respect, or with a view to soften the force of a direct expression, or for other reason.',
  },
  'Circumlocutory': {
    'id': 9703,
    'definition': '<b>CIRCUMLOCUTORY</b>, <i>a.</i> Pertaining to circumlocution; consisting or contained in a compass of words; periphrastic.',
  },
  'Circummured': {
    'id': 9704,
    'definition': '<b>CIRCUMMURED</b>, <i>a.</i> Walled round; encompassed with a wall.',
  },
  'Circumnavigable': {
    'id': 9705,
    'definition': '<b>CIRCUMNAVIGABLE</b>, <i>a.</i> [See <a href="dict://Circumnavigate">Circumnavigate</a>.] That may be sailed round.',
  },
  'Circumnavigate': {
    'id': 9706,
    'definition': '<b>CIRCUMNAVIGATE</b>, <i>v.t.</i> To sail round; to pass round by water; as, to circumnavigate the globe.',
  },
  'Circumnavigation': {
