  'Cistern': {
    'id': 9760,
    'definition': '<b>CISTERN</b>, <i>n.<br><br></i> 1. An artificial reservoir or receptacle for holding water, beer or other liquor, as in domestic uses, distilleries, and breweries.<br><br>2. A natural reservoir; a hollow place containing water; as a fountain or lake.',
  },
  'Cistic': {
    'id': 9761,
    'definition': '<b>CISTIC</b>, <i>a.</i> [See <a href="dict://Cystic">Cystic</a>.]',
