  'Clamber': {
    'id': 9823,
    'definition': '<b>CLAMBER</b>, <i>v.i.</i> [from climb, or D. Klampen, to grapple.] To climb with difficulty, or with hands and feet.',
  },
  'Clambering': {
    'id': 9824,
    'definition': '<b>CLAMBERING</b>, <i>ppr.</i> Climbing with effort and labor.',
