  'Clandestine': {
    'id': 9839,
    'definition': '<b>CLANDESTINE</b>, <i>a.</i> Secret; private; hidden; withdrawn from public view. It often bears an ill sense, as implying craft or deception, or evil design.',
  },
  'Clandestinely': {
    'id': 9840,
    'definition': '<b>CLANDESTINELY</b>, <i>adv.</i> Secretly; privately; in secret.',
