  'Comically': {
    'id': 10725,
    'definition': '<b>COMICALLY</b>, <i>adv.<br><br></i> 1. In a manner befitting comedy.<br><br>2. In a comical manner; in a manner to raise mirth.',
  },
  'Comicalness': {
    'id': 10726,
    'definition': '<b>COMICALNESS</b>, <i>n.</i> The quality of being comical; the power or quality of raising mirth.',
