  'Conglutinant': {
    'id': 11535,
    'definition': '<b>CONGLUTINANT</b>, <i>a.</i> [See <a href="dict://Conglutinate">Conglutinate</a>.] Gluing; uniting; healing.<br><br><b>CONGLUTINANT</b>, <i>n.</i> A medicine that heals wounds.',
  },
  'Conglutinate': {
    'id': 11536,
    'definition': '<b>CONGLUTINATE</b>, <i>v.t.</i> [L., glue. See <a href="dict://Glue">Glue</a>.]<br><br>1. To glue together; to unite by some glutinous or tenacious substance.<br><br>2. To heal; to unite the separated parts of a wound by tenacious substance.<br><br><b>CONGLUTINATE</b>, <i>v.i.</i> To coalesce; to unite by the intervention of a callus.',
  },
  'Conglutinated': {
