  'Convexity': {
    'id': 12156,
    'definition': '<b>CONVEXITY</b>, <i>n.</i> [L.] The exterior surface of a convex body; a gibbous or globular form; roundness.',
  },
  'Convexly': {
    'id': 12157,
    'definition': '<b>CONVEXLY</b>, <i>adv.</i> In a convex form; as a body convexly conical.',
