  'Counselable': {
    'id': 12637,
    'definition': '<b>COUNSELABLE</b>, <i>a.</i> Willing to receive counsel; disposed to follow the advice or opinions of others.',
  },
  'Counseled': {
    'id': 12638,
    'definition': '<b>COUNSELED</b>, <i>pp.</i> Advised; instructed; admonished.',
