  'Crocalite': {
    'id': 13167,
    'definition': '<b>CROCALITE</b>, <i>n.</i> A mineral, a variety of zeolite, of an orange or brick red color. It is sometimes found in reniform or globular masses, with a radiated texture.',
  },
  'Croceous': {
    'id': 13168,
    'definition': '<b>CROCEOUS</b>, <i>a.</i> [L.] Like saffron; yellow; consisting of saffron.',
