  'Curling': {
    'id': 13554,
    'definition': '<b>CURLING</b>, <i>ppr.</i> Bending; twisting; forming into ringlets.',
  },
  'Curling-Irons': {
    'id': 13555,
    'definition': '<b>CURLING-IRONS, CURLING-TONGS</b>, <i>n.</i> An instrument for curling the hair.',
