  'Debark': {
    'id': 13993,
    'definition': '<b><b>DEB\'ARK</b>, <i>v.t.</i> To land from a ship or boat; to remove from on board any water-craft, and place on land; to disembark; as, to debark artillery.',
  },
  'Debarkation': {
    'id': 13994,
    'definition': '<b><b>DEBARKA\'TION</b>, <i>n.</i> The act of disembarking.',
