  'Decaliter': {
    'id': 14052,
    'definition': '<b><b>DEC\'ALITER</b>, <i>n.</i> [Gr., ten and liter.] A French measure of capacity, containing ten liters, or 610.28 cubic inches, equal to two gallons and 64,44231 cubic inches.',
  },
  'Decalogist': {
    'id': 14053,
    'definition': '<b><b>DECAL\'OGIST</b>, <i>n.</i> One who explains the decalogue.',
  },
  'Decalogue': {
    'id': 14054,
    'definition': '<b><b>DEC\'ALOGUE</b>, <i>n.</i> dec\'alog. [Gr., ten and speech.] The ten commandments or precepts given by God to Moses at mount Sinai, and originally written on two tables of stone.',
  },
  'Decameter': {
    'id': 14055,
    'definition': '<b><b>DECAM\'ETER</b>, <i>n.</i> [Gr., ten and measure.] A French measure of length, consisting of ten meters, and equal to 393 English inches, and 71 decimals.',
  },
  'Decamp': {
    'id': 14056,
    'definition': '<b><b>DECAMP\'</b>, <i>v.i.</i> To remove or depart from a camp; to march off; as, the army decamped at six o\'clock.',
  },
  'Decampment': {
