  'Deliquesce': {
    'id': 14570,
    'definition': '<b>DELIQUESCE</b>, <i>v.i.</i> [L. To melt; to melt or become soft.] To melt gradually and become liquid by attracting and absorbing moisture from the air; as certain salts, acids and alkalies.',
  },
  'Deliquescence': {
    'id': 14571,
    'definition': '<b>DELIQUESCENCE</b>, <i>n.</i> Spontaneous liquefaction in the air; a gradual melting or becoming liquid by absorption of water from the atmosphere.',
  },
  'Deliquescent': {
    'id': 14572,
    'definition': '<b>DELIQUESCENT</b>, <i>a.</i> Liquefying in the air; capable of attracting moisture from the atmosphere and becoming liquid; as deliquescent salts.',
  },
  'Deliquiate': {
    'id': 14573,
    'definition': '<b>DELIQUIATE</b>, <i>v.i.</i> To melt and become liquid by imbibing water from the air.',
  },
  'Deliquiation': {
    'id': 14574,
    'definition': '<b>DELIQUIATION</b>, <i>n.</i> A melting by attracting water from the air.',
