    'definition': '<b>DEMENTATE</b>, <i>a.</i> Mad; infatuated.<br><br><b>DEMENTATE</b>, <i>v.t.</i> To make mad.',
  },
  'Dementation': {
    'id': 14626,
    'definition': '<b>DEMENTATION</b>, <i>n.</i> The act of making frantic.',
  },
  'Demephitization': {
    'id': 14627,
    'definition': '<b>DEMEPHITIZATION</b>, <i>n.</i> The act of purifying from mephitic or foul air.',
  },
  'Demephitize': {
    'id': 14628,
    'definition': '<b>DEMEPHITIZE</b>, <i>v.t.</i> To purify from foul unwholesome air.',
  },
  'Demephitized': {
    'id': 14629,
    'definition': '<b>DEMEPHITIZED</b>, <i>pp.</i> Purified; freed from foul air.',
