  'Deplumation': {
    'id': 14860,
    'definition': '<b>DEPLUMATION</b>, <i>n.</i><br><br>1. The stripping or falling off of plumes or feathers.<br><br>2. A tumor of the eye-lids with loss of hair.',
  },
  'Deplume': {
    'id': 14861,
    'definition': '<b>DEPLUME</b>, <i>v.t.</i> [L. A feather.] To strip or pluck off feathers; to deprive of plumage.',
  },
  'Deplumed': {
