    'definition': '<b>DISROBED</b>, <i>pp.</i> Divested of clothing; stripped of covering.',
  },
  'Disrober': {
    'id': 16579,
    'definition': '<b>DISROBER</b>, <i>n.</i> One that strips of robes or clothing.',
  },
  'Disrobing': {
    'id': 16580,
    'definition': '<b>DISROBING</b>, <i>ppr.</i> Divesting of garments; stripping of any kind of covering.',
