    'definition': '<b>DOCTORAL</b>, <i>a.</i> Relating to the degree of a doctor.',
  },
  'Doctorally': {
    'id': 16943,
    'definition': '<b>DOCTORALLY</b>, <i>adv.</i> In the manner of a doctor.',
  },
  'Doctorate': {
    'id': 16944,
    'definition': '<b>DOCTORATE</b>, <i>n.</i> The degree of a doctor.<br><br><b>DOCTORATE</b>, <i>v.t.</i> To make a doctor by conferring a degree.',
  },
  'Doctoress': {
