    'definition': '<b>DREADABLE</b>, <i>a.</i> That is to be dreaded. [Not used.]',
  },
  'Dreaded': {
    'id': 17386,
    'definition': '<b>DREADED</b>, <i>pp.</i> Feared.',
  },
  'Dreader': {
    'id': 17387,
    'definition': '<b>DREADER</b>, <i>n.</i> One that fears, or lives in fear.',
