  'Eyeshot': {
    'id': 20571,
    'definition': '<b>EY\'ESHOT</b>, <i>n.</i> Sight; view; glance of the eye.',
  },
  'Eyesight': {
    'id': 20572,
    'definition': '<b>EY\'ESIGHT</b>, <i>n.</i> The sight of the eye; view; observation. Psa 18.<br><br>Josephus sets this down from his own eyesight.<br><br>1. The sense of seeing. His eyesight fails.',
  },
  'Eyesore': {
