    'definition': '<b>FIG\'URE-CASTER,<br><br>FIG\'URE-FLINGER</b>, <i>n.</i> A pretender to astrology.',
  },
  'Figure-Stone': {
    'id': 21411,
    'definition': '<b>FIG\'URE-STONE</b>, <i>n.</i> A name of the agalmatolite, or bildstein.',
