  'Figuring': {
    'id': 21413,
    'definition': '<b>FIG\'URING</b>, <i>ppr.</i> Forming into determinate shape; representing by types or resemblances; adorning with figures; making a distinguished appearance.',
  },
  'Filaceous': {
    'id': 21414,
    'definition': '<b>FILA\'CEOUS</b>, <i>a.</i> [L. filum, a thread.] Composed or consisting of threads.',
