  'Fleam': {
    'id': 21794,
    'definition': '<b>FLEAM</b>, <i>n.<br><br></i> In surgery and farriery, a sharp instrument used for opening veins for letting blood.',
  },
  'Fleawort': {
    'id': 21795,
    'definition': '<b>FLE\'AWORT</b>, <i>n.</i> A plant.',
