  'Foreboding': {
    'id': 22264,
    'definition': '<b>FOREBO\'DING</b>, <i>ppr.</i> Prognosticating; foretelling; foreknowing.<br><br><b>FOREBO\'DING</b>, <i>n.</i> Prognostication.',
