  'Freshwater': {
    'id': 22789,
    'definition': '<b>FRESH\'WATER</b>, <i>a.<br><br></i> 1. Accustomed to sail on freshwater only, or in the coasting trade; as a freshwater sailor.<br><br>2. Raw; unskilled.',
  },
  'Freshwatered': {
    'id': 22790,
    'definition': '<b>FRESH\'WATERED</b>, <i>a.</i> Newly watered; supplied with fresh water.',
