  'Gagger': {
    'id': 23245,
    'definition': '<b>GAG\'GER</b>, <i>n.</i> One that gags.',
  },
  'Gaggle': {
    'id': 23246,
    'definition': '<b>GAG\'GLE</b>, <i>v.i.</i> To make a noise like a goose.',
