  'Gainful': {
    'id': 23256,
    'definition': '<b>GA\'INFUL</b>, <i>a.</i> Producing profit or advantage; profitable; advantageous; advancing interest or happiness.<br><br>1. Lucrative; productive of money; adding to the wealth or estate.',
  },
  'Gainfully': {
    'id': 23257,
    'definition': '<b>GA\'INFULLY</b>, <i>adv.</i> With increase of wealth; profitably; advantageously.',
