  'Goats-Rue': {
    'id': 24127,
    'definition': '<b>GOAT\'S-RUE</b>, <i>n.</i> A plant of the genus Galega.',
  },
  'Goats-Stones': {
    'id': 24128,
    'definition': '<b>GOAT\'S-STONES</b>, <i>n.</i> The greater goat\'s stones is the Satyrium; the lesser,the Orchis.',
  },
  'Goats-Thorn': {
    'id': 24129,
    'definition': '<b>GOAT\'S-THORN</b>, <i>n.</i> A plant of the genus Astragalus.',
