  'Heavenly-Mindedness': {
    'id': 25649,
    'definition': '<b>HEAVENLY-MINDEDNESS</b>, <i>n.</i> The state of having the affections placed on heavenly things and spiritual objects.',
  },
  'Heavenward': {
    'id': 25650,
    'definition': '<b>HEAV\'ENWARD</b>, <i>adv.</i> Toward heaven.',
