  'Hedenbergite': {
    'id': 25693,
    'definition': '<b>HEDENBERG\'ITE</b>, <i>n.</i> [from Hedenberg, who first analyzed it.]<br><br>A mineral, or ore of iron, in masses, composed of shining plates, which break into rhombic fragments; found at Tunaberg, in Sweden.',
  },
  'Hederaceous': {
    'id': 25694,
    'definition': '<b>HEDERA\'CEOUS</b>, <i>a.</i> [L. hederaceus, from hedera, ivy.]<br><br>1. Pertaining to ivy.<br><br>2. Producing ivy.',
  },
  'Hederal': {
    'id': 25695,
    'definition': '<b>HED\'ERAL</b>, <i>a.</i> Composed of ivy; belonging to ivy.',
