  'Helminthology': {
    'id': 25782,
    'definition': '<b>HELMINTHOL\'OGY</b>, <i>n.</i> [Gr. a worm, and discourse.] The science or knowledge of vermes; the description and natural history of vermes.',
  },
  'Helmless': {
    'id': 25783,
    'definition': '<b>HELM\'LESS</b>, <i>a.</i> Destitute of a helmet.<br><br>1. Without a helm.',
