  'Hobbler': {
    'id': 26261,
    'definition': '<b>HOB\'BLER</b>, <i>n.</i> One that hobbles.<br><br><b>HOB\'BLER</b>, <i>n.</i> [from hobby.] One who by his tenure was to maintain a hobby for military service; or one who served as a soldier on a hobby with light armor.',
  },
  'Hobbling': {
    'id': 26262,
    'definition': '<b>HOB\'BLING</b>, <i>ppr.</i> Walking with a halting or interrupted step.',
