  'Hod': {
    'id': 26278,
    'definition': '<b>HOD</b>, <i>n.</i> A kind of tray for carrying mortar and brick,used in bricklaying. It is fitted with a handle and borne on the shoulder.',
  },
  'Hoddy-Doddy': {
    'id': 26279,
    'definition': '<b>HOD\'DY-DODDY</b>, <i>n.</i> An awkward or foolish person.',
