  'Hodge-Podge': {
    'id': 26280,
    'definition': '<b>HODGE-PODGE<br><br>HODIERN\'AL</b>, <i>a.</i> [L. hodiernus, from hodie, hoc die,this day.]<br><br>Of this day; belonging to the present day.',
  },
  'Hodman': {
    'id': 26281,
    'definition': '<b>HOD\'MAN</b>, <i>n.</i> A man who carries a hod; a mason\'s tender.',
