  'Hogged': {
    'id': 26289,
    'definition': '<b>HOG\'GED</b>, <i>pp.</i> Scraped under water.<br><br>1. Curving; having the ends lower than the middle.',
  },
  'Hoggerel': {
    'id': 26290,
    'definition': '<b>HOG\'GEREL</b>, <i>n.</i> A sheep of the second year.<br><br>A two year old ewe.',
