  'Hogget': {
    'id': 26291,
    'definition': '<b>HOG\'GET</b>, <i>n.</i> A sheep two years old.<br><br>1. A colt of a year old, called also hog-colt. [Local.]<br><br>2. A young boar of the second year.',
  },
  'Hoggish': {
    'id': 26292,
    'definition': '<b>HOG\'GISH</b>, <i>a.</i> Having the qualities of a hog; brutish; gluttonous; filthy; meanly selfish.',
