  },
  'Honeyed': {
    'id': 26421,
    'definition': '<b>HON\'EYED</b>, <i>a.</i> Covered with honey.<br><br>1. Sweet; as honeyed words.',
  },
  'Honeyless': {
    'id': 26422,
    'definition': '<b>HON\'EYLESS</b>, <i>a.</i> Destitute of honey.',
