  'Hurtless': {
    'id': 26863,
    'definition': '<b>HURT\'LESS</b>, <i>a.</i> Harmless; innocent; doing no injury; innoxious; as hurtless blows.<br><br>1. Receiving no injury.',
  },
  'Hurtlessly': {
    'id': 26864,
    'definition': '<b>HURT\'LESSLY</b>, <i>adv.</i> Without harm. [Little used.]',
