  'Hybernacle': {
    'id': 26902,
    'definition': '<b>HYBERNACLE<br><br>HYBERNATE<br><br>HYBERNATION</b>. See <a href="dict://Hibernacle,">Hibernacle,</a> Hibernate, Hibernation.',
