  'Incalculable': {
    'id': 28014,
    'definition': '<b>INCAL\'CULABLE</b>, <i>a.</i> That cannot be calculated; beyond calculation.',
  },
  'Incalculably': {
    'id': 28015,
    'definition': '<b>INCAL\'CULABLY</b>, <i>adv.</i> In a degree beyond calculation.',
