  'Koupholite': {
    'id': 31102,
    'definition': '<b>KOUPH\'OLITE</b>, <i>n.</i> [Gr. light, and stone.]<br><br>A mineral, regarded as a variety of prehnite. It occurs in minute rhomboidal plates, of a greenish or yellowish white, translucid, glistening and pearly. It is found in the Pyrenees.',
  },
  'Kraal': {
    'id': 31103,
    'definition': '<b>KRAAL</b>, <i>n.</i> In the southern part of Africa, among the Hottentots, a village; a collection of huts.',
  },
  'Krag': {
    'id': 31104,
    'definition': '<b>KRAG</b>, <i>n.</i> A species of argillaceous earth.',
