  'Lichenography': {
    'id': 31898,
    'definition': '<b>LICHENOG\'RAPHY</b>, <i>n.</i> [lichen and to write.]<br><br>A description of the vegetables called lichens; the science which illustrates the natural history of the lichens.',
  },
  'Licit': {
    'id': 31899,
    'definition': '<b>LIC\'IT</b>, <i>a.</i> [L. licitus.] Lawful.',
  },
  'Licitly': {
    'id': 31900,
    'definition': '<b>LIC\'ITLY</b>, <i>adv.</i> Lawfully.',
