  'Limmer': {
    'id': 32040,
    'definition': '<b>LIM\'MER</b>, <i>n.<br><br></i> 1. A limehound; a mongrel.<br><br>2. A dog engendered between a hound and a mastiff.<br><br>3. A thill or shaft. [Local. See <a href="dict://Limber">Limber</a>.]<br><br>4. A thill-horse. [Local.]',
  },
  'Limn': {
    'id': 32041,
    'definition': '<b>LIMN</b>, <i>v.t.</i> lim. [L. lumino.] To draw or paint; or to paint in water colors.',
  },
  'Limned': {
    'id': 32042,
    'definition': '<b>LIM\'NED</b>, <i>pp.</i> lim\'med. Painted.',
