  'Limner': {
    'id': 32043,
    'definition': '<b>LIM\'NER</b>, <i>n.</i> [L. illuminator, in the middle ages, alluminor.]<br><br>1. One that colors or paints on paper or parchment; one who decorates books with initial pictures.<br><br>2. A portrait painter.',
  },
  'Limning': {
    'id': 32044,
    'definition': '<b>LIMN\'ING</b>, <i>ppr.</i> Drawing; painting; painting in water colors.<br><br><b>LIM\'NING</b>, <i>n.</i> The act or art of drawing or painting in water colors.',
  },
  'Limous': {
    'id': 32045,
    'definition': '<b>LI\'MOUS</b>, <i>a.</i> [L. limosus, from limus, slime.] Muddy; slimy; thick.',
