  'Limpet': {
    'id': 32048,
    'definition': '<b>LIM\'PET</b>, <i>n.</i> [L. lepas; Gr. from to peel or strip off bark.]<br><br>A univalve shell of the genus Patella, adhering to rocks.',
  },
  'Limpid': {
    'id': 32049,
    'definition': '<b>LIM\'PID</b>, <i>a.</i> [L. limpidus.] Pure; clear; transparent; as a limpid stream.',
