  'Mallet': {
    'id': 33030,
    'definition': '<b>MAL\'LET</b>, <i>n.</i> [L.malleus.] A wooden hammer or instrument for beating, or for driving pins; particularly used in carpentry, for driving the chisel.',
  },
  'Mallow': {
    'id': 33031,
    'definition': '<b>MALLOW</b>, <i>n.</i> [L. malva; Gr. soft; Eng. mellow.]<br><br>A plant of the genus Malva; so called form its emollient qualities.<br><br>Marsh-mallows, a plant of the genus Althaea.',
  },
  'Malmsey': {
    'id': 33032,
    'definition': '<b>MALM\'SEY</b>, <i>n.</i> [L. vinum arvisium.] The name of a species of grape, and also of a kind of wine.',
  },
  'Malpractice': {
    'id': 33033,
    'definition': '<b>MALPRAC\'TICE</b>, <i>n.</i> [mal and practice.] Evil practice; illegal or immoral conduct; practice contrary to established rules.',
  },
  'Malt': {
    'id': 33034,
    'definition': '<b>MALT</b>, <i>n.</i> Barley steeped in water, fermented and dried in a kiln, and thus prepared for brewing into ale or beer.<br><br><b>MALT</b>, <i>v.t.</i> To make into malt; as, to malt barley.<br><br><b>MALT</b>, <i>v.i.</i> To become malt.<br><br>To house it green will make it malt worse.<br><br><b>MALT\'-DRINK<br><br>MALT\'-LIQUOR</b>, <i>n.</i> A liquor prepared for drink by an infusion of malt; as beer, ale, porter, &c.',
  },
  'Malt-Dust': {
    'id': 33035,
    'definition': '<b>MALT\'-DUST</b>, <i>n.</i> The grains or remains of malt.<br><br>Malt-dust is an enricher of barren land.<br><br><b>MALT\'-FLOOR</b>, <i>n.</i> A floor for drying malt.<br><br><b>MALT\'-HORSE</b>, <i>n.</i> A horse employed in grinding malt; hence, a dull fellow.',
