  'Market-Price': {
    'id': 33329,
    'definition': '<b>M`ARKET-PRICE<br><br>M`ARKET-RATE</b>, <i>n.</i> The current price of commodities at any given time.',
  },
  'Market-Town': {
    'id': 33330,
    'definition': '<b>M`ARKET-TOWN</b>, <i>n.</i> A town that has the privilege of a stated public market.',
