  'Mazard': {
    'id': 33593,
    'definition': '<b>MAZ\'ARD</b>, <i>n.</i> [probably from the root of marsh.]<br><br>1. The jaw. [Not used.]<br><br>2. A kind of cherry.<br><br><b>MAZ\'ARD</b>, <i>v.t.</i> To knock on the head. [Not in use.]',
  },
  'Mazarine': {
    'id': 33594,
    'definition': '<b>MAZARINE</b>, <i>n.</i> A deep blue color.<br><br>1. A particular way of dressing fowls.<br><br>2. A little dish set in a larger one.',
  },
  'Maze': {
    'id': 33595,
    'definition': '<b>MAZE</b>, <i>n.<br><br></i> 1. A winding and turning; perplexed state of things; intricacy; a state that embarrasses.<br><br>The ways of heaven are dark and intricate,<br><br>Puzzled with mazes, and perplexed with error.<br><br>2. Confusion of thought; perplexity; uncertainty.<br><br>3. A labyrinth.<br><br><b>MAZE</b>, <i>v.t.</i> To bewilder; to confound with intricacy; to amaze.<br><br><b>MAZE</b>, <i>v.i.</i> To be bewildered.',
  },
  'Mazedness': {
    'id': 33596,
    'definition': '<b>MA\'ZEDNESS</b>, <i>n.</i> Confusion; astonishment.',
  },
  'Mazer': {
    'id': 33597,
    'definition': '<b>MA\'ZER</b>, <i>n.</i> A maple cup.',
  },
  'Mazological': {
