  'Mephitis': {
    'id': 33859,
    'definition': '<b>MEPH\'ITIS<br><br>MEPH\'ITISM</b>, <i>n.</i> Foul, offensive or noxious exhalations from dissolving substances, filth or other source; also,carbonic acid gas.',
  },
  'Mercantante': {
    'id': 33860,
    'definition': '<b>MERCANTAN\'TE</b>, <i>n.</i> A foreign trader. [Not in use.]',
  },
  'Mercantile': {
    'id': 33861,
    'definition': '<b>MER\'CANTILE</b>, <i>a.</i> [L. mercans, mercor, to buy.]<br><br>1. Trading; commercial; carrying on commerce; as mercantile nations; the mercantile class of men.<br><br>2. Pertaining or relating to commerce or trade; as mercantile business.',
  },
  'Mercat': {
    'id': 33862,
    'definition': '<b>MER\'CAT</b>, <i>n.</i> [L. mercatus.] Market; trade. [Not in use.]',
  },
  'Mercenarily': {
    'id': 33863,
    'definition': '<b>MER\'CENARILY</b>, <i>adv.</i> In a mercenary manner.',
  },
  'Mercenariness': {
    'id': 33864,
    'definition': '<b>MER\'CENARINESS</b>, <i>n.</i> [from mercenary.]<br><br>Venality; regard to hire or reward.',
  },
  'Mercenary': {
    'id': 33865,
    'definition': '<b>MER\'CENARY</b>, <i>a.</i> [L. mercenarius, from merces, reward, wages, mercor, to guy.]<br><br>1. Venal; that may be hired; actuated by the hope of reward; moved by the love of money; as a mercenary prince or judge.<br><br>2. Hired; purchased by money; as mercenary services; mercenary soldiers.<br><br>3. Sold for money; as mercenary blood.<br><br>4. Greedy of gain; mean; selfish; as a mercenary disposition.<br><br>5. Contracted from motives of gain; as a mercenary marriage.<br><br><b>MER\'CENARY</b>, <i>n.</i> One who is hired; a soldier that is hired into foreign service; a hireling.',
  },
  'Mercer': {
    'id': 33866,
    'definition': '<b>MER\'CER</b>, <i>n.</i> [L. merx, wares, commodities.]<br><br>One who deals in silks.',
  },
  'Mercership': {
    'id': 33867,
    'definition': '<b>MER\'CERSHIP</b>, <i>n.</i> The business of a mercer.',
  },
  'Mercery': {
    'id': 33868,
    'definition': '<b>MER\'CERY</b>, <i>n.</i> The commodities or goods in which a mercer deals; trade of mercers.',
  },
  'Merchand': {
    'id': 33869,
    'definition': '<b>MER\'CHAND</b>, <i>v.i.</i> To trade. [Not used.]',
  },
  'Merchandise': {
    'id': 33870,
    'definition': '<b>MER\'CHANDISE</b>, <i>n.<br><br></i> 1. The objects of commerce; wares, goods, commodities, whatever is usually bought or sold in trade. But provisions daily sold in market, horses, cattle, and fuel are not usually included in the term,and real estate never.<br><br>2. Trade; traffick; commerce.<br><br><b>MER\'CHANDISE</b>, <i>v.i.</i> To trade; to carry on commerce.',
  },
  'Merchandry': {
    'id': 33871,
    'definition': '<b>MER\'CHANDRY</b>, <i>n.</i> Trade; commerce. [Not in use.]',
