    'definition': '<b>MIS\'ANTHROPE<br><br>MISANTHROP\'IC<br><br>MISANTHROP\'ICAL</b>, <i>a.</i> Hating or having a dislike to mankind.',
  },
  'Misanthropist': {
    'id': 34328,
    'definition': '<b>MISAN\'THROPIST</b>, <i>n.</i> [Gr. to hate, and man.] A hater of mankind.',
