    'definition': '<b>MISBECOM\'INGNESS</b>, <i>n.</i> Unbecomingness; unsuitableness.',
  },
  'Misbegot': {
    'id': 34344,
    'definition': '<b>MISBEGOT\'<br><br>MISBEGOT\'TEN</b>, <i>ppr.</i> or a. Unlawfully or irregularly begotten.',
  },
  'Misbehave': {
    'id': 34345,
    'definition': '<b>MISBEHA\'VE</b>, <i>v.i.</i> To behave ill; to conduct one\'s self improperly.',
  },
  'Misbehaved': {
