    'definition': '<b>MISBEHA\'VED</b>, <i>a.</i> Guilty of ill behavior; ill bred; rude.',
  },
  'Misbehavior': {
    'id': 34347,
    'definition': '<b>MISBEHA\'VIOR</b>, <i>n.</i> misbeha\'vyor. Ill conduct; improper, rude or uncivil behavior.',
  },
  'Misbelief': {
    'id': 34348,
    'definition': '<b>MISBELIE\'F</b>, <i>n.</i> Erroneous belief; false religion.',
