  'Miscreance': {
    'id': 34408,
    'definition': '<b>MIS\'CREANCE<br><br>MIS\'CREANCY</b>, <i>n.</i> [See <a href="dict://Miscreant">Miscreant</a>.] Unbelief; false faith; adherence to a false religion.',
  },
  'Miscreant': {
    'id': 34409,
    'definition': '<b>MIS\'CREANT</b>, <i>n.</i> [L. credens, credo.]<br><br>1. An infidel, or one who embraces a false faith.<br><br>2. A vile wretch; an unprincipled fellow.',
  },
  'Miscreate': {
