  'Muckworm': {
    'id': 35275,
    'definition': 'MUCK\'WORM, n. A worm that lives in muck.<br><br>1. A miser; one who scrapes together money by mean labor and devices.',
  },
  'Mucky': {
    'id': 35276,
    'definition': '<b>MUCK\'Y</b>, <i>a.</i> Filthy; nasty.',
