  'Mulatto': {
    'id': 35310,
    'definition': '<b>MULAT\'TO</b>, <i>n.</i> [L. mulus, a mule.] A person that is the offspring of a negress by a white man, or of a white woman by a negro.',
  },
  'Mulberry': {
    'id': 35311,
    'definition': '<b>MUL\'BERRY</b>, <i>n.</i> The berry or fruit of a true of the genus Morus.',
