  'Pandit': {
    'id': 38218,
    'definition': '<b>PAN\'DIT<br><br>PUN\'DIT</b>, <i>n.</i> In Hindoostan, a learned man.',
  },
  'Pandoran': {
    'id': 38219,
    'definition': '<b>PAN\'DORAN</b>, <i>n.</i> [Gr.] An instrument of music of the lute kind; a bandore.',
  },
  'Pandore': {
    'id': 38220,
    'definition': '<b>PAN\'DORE<br><br>PANE</b>, <i>n.</i> A square of glass.<br><br>1. A piece of any thing in variegated works.',
  },
  'Panegyric': {
    'id': 38221,
    'definition': '<b>PANEGYR\'IC</b>, <i>n.</i> [L. panegyricus, from Gr. a public meeting or celebration, all, and an assembly.]<br><br>1. An oration or eulogy in praise of some distinguished person or achievement; a formal or elaborate encomium.<br><br>2. An encomium; praise bestowed on some eminent person, action or virtue.<br><br><b>PANEGYR\'IC</b>, <i>a.</i> Containing praise or eulogy; encomiastic.',
  },
  'Panegyris': {
    'id': 38222,
    'definition': '<b>PANEGY\'RIS</b>, <i>n.</i> A festival; a public meeting.',
  },
  'Panegyrist': {
    'id': 38223,
    'definition': '<b>PANEGYR\'IST</b>, <i>n.</i> One who bestows praise; an eulogist; an encomiast, either by writing or speaking.',
  },
  'Panegyrize': {
    'id': 38224,
    'definition': '<b>PAN\'EGYRIZE</b>, <i>v.t.</i> To praise highly; to write or pronounce an eulogy on.<br><br><b>PAN\'EGYRIZE</b>, <i>v.i.</i> To bestow praises.',
  },
  'Panegyrized': {
    'id': 38225,
    'definition': '<b>PAN\'EGYRIZED</b>, <i>pp.</i> Highly praised or eulogized.',
