  'Pantler': {
    'id': 38259,
    'definition': '<b>PANT\'LER</b>, <i>n.</i> [L. panis, bread.] The officer in a great family who has charge of the bread.',
  },
  'Pantofle': {
    'id': 38260,
    'definition': '<b>PAN\'TOFLE</b>, <i>n.</i> A slipper for the foot.',
  },
  'Pantograph': {
