  'Passing': {
    'id': 38574,
    'definition': '<b>P`ASSING</b>, <i>ppr.</i> Moving; proceeding.<br><br>1. a. Exceeding; surpassing; eminent.<br><br>2. Adverbially used to enforce or enhance the meaning of another word; exceedingly; as passing fair; passing strange.',
  },
  'Passing-Bell': {
