  'Phytography': {
    'id': 39654,
    'definition': '<b>PHYTOG\'RAPHY</b>, <i>n.</i> [Gr. a plant, and description.] A description of plants.',
  },
  'Phytolite': {
    'id': 39655,
    'definition': '<b>PHYT\'OLITE</b>, <i>n.</i> [Gr. a plant, and a stone.] A plant petrified, or fossil vegetable.',
