  'Plain-Song': {
    'id': 39989,
    'definition': '<b>PLA\'IN-SONG</b>, <i>n.</i> The plain unvaried chant of churches; so called in contradistinction from the prick-song, or variegated music sung by note.',
  },
  'Plain-Spoken': {
    'id': 39990,
    'definition': '<b>PLA\'IN-SPOKEN</b>, <i>a.</i> Speaking with plain, unreserved sincerity.',
