    'definition': '<b>PRA\'ISELESS</b>, <i>a.</i> Without praise or commendation.',
  },
  'Praiser': {
    'id': 40905,
    'definition': '<b>PRA\'ISER</b>, <i>n.</i> One who praises, commends or extols; an applauder; a commender.',
  },
  'Praiseworthily': {
    'id': 40906,
    'definition': '<b>PRAISEWORTHILY</b>, <i>adv.</i> In a manner deserving of commendation.',
