    'definition': '<b>PRE-ENGA\'GING</b>, <i>ppr.</i> Previously engaging.',
  },
  'Pre-Establish': {
    'id': 40951,
    'definition': '<b>PRE-ESTAB\'LISH</b>, <i>v.t.</i> [pre and establish.]<br><br>To establish or settle beforehand.',
  },
  'Pre-Established': {
