  'Preintimation': {
    'id': 41170,
    'definition': '<b>PREINTIMA\'TION</b>, <i>n.</i> [pre and intimation.]<br><br>Previous intimation; a suggestion beforehand.',
  },
  'Prejudge': {
    'id': 41171,
    'definition': '<b>PREJUDGE</b>, <i>v.t.</i> prejudg\'. [L. proe and judico, to judge.]<br><br>1. To judge in a cause before it is heard, or before the arguments and facts in the case are fully known.<br><br>The committee of council hath prejudged the whole case, by calling the united sense of both houses of parliament an universal clamor.<br><br>2. To judge and determine before the cause is heard; hence sometimes, to condemn beforehand or unheard.',
  },
  'Prejudged': {
    'id': 41172,
    'definition': '<b>PREJUDG\'ED</b>, <i>pp.</i> Judged beforehand; determined unheard.',
  },
  'Prejudging': {
    'id': 41173,
    'definition': '<b>PREJUDG\'ING</b>, <i>ppr.</i> Judging or determining without a hearing or before the case is fully understood.',
