  'Primordial': {
    'id': 41546,
    'definition': '<b>PRIMOR\'DIAL</b>, <i>a.</i> [L. primordialis, primordium; primus, first, and ordo, order.] First in order; original; existing from the beginning.<br><br><b>PRIMOR\'DIAL</b>, <i>n.</i> Origin; first principle or element.',
  },
  'Primordian': {
