    'definition': '<b>PROMULGE</b>, <i>v.t.</i> promulj\'. To promulgate; to publish or teach. [Less used than promulgate.]',
  },
  'Promulged': {
    'id': 41904,
    'definition': '<b>PROMULG\'ED</b>, <i>pp.</i> Published.',
  },
  'Promulger': {
    'id': 41905,
    'definition': '<b>PROMULG\'ER</b>, <i>n.</i> One who publishes or teaches what was before unknown.',
  },
  'Promulging': {
    'id': 41906,
    'definition': '<b>PROMULG\'ING</b>, <i>ppr.</i> Publishing.',
