  'Querent': {
    'id': 42854,
    'definition': '<b>QUE\'RENT</b>, <i>n.</i> [L. querens, queror, to complain.]<br><br>The complainant; the plaintiff. [Not in use.]<br><br><b>QUE\'RENT</b>, <i>n.</i> [L. quaerens, quaero, to inquire.]<br><br>To inquirer. [Not much used.]',
  },
  'Querimonious': {
    'id': 42855,
    'definition': '<b>QUERIMO\'NIOUS</b>, <i>a.</i> [L. querimonia, complaint, from queror.]<br><br>Complaining; querulous; apt to complain.',
