  'Quern': {
    'id': 42862,
    'definition': '<b>QUERN</b>, <i>n.<br><br></i> A hand-mill for grinding grain; a mill, the stone of which was turned by hand, used before the invention of windmills and watermills.',
  },
  'Querpo': {
    'id': 42863,
    'definition': '<b>QUERP\'O</b>, <i>n.</i> [L. corpus.]<br><br>A waistcoat or garment close to the body.',
