    'definition': '<b>RA\'PIER-FISH</b>, <i>n.</i> The sword-fish.',
  },
  'Rapil': {
    'id': 43223,
    'definition': '<b>RAP\'IL,<br><br>RAPIL\'LO</b>, <i>n.</i> Pulverized volcanic substances.',
