  'Re-Embark': {
    'id': 43369,
    'definition': '<b>RE-EMB\'ARK</b>, <i>v.t.</i> [re and embark.] To embark or put on board again.<br><br><b>RE-EMB\'ARK</b>, <i>v.i.</i> To embark or go on board again.',
  },
  'Re-Embarkation': {
