  'Rearward': {
    'id': 43506,
    'definition': '<b>RE\'ARWARD</b>, <i>n.</i> [from rear. See <a href="dict://Rereward">Rereward</a>.]<br><br>1. The last troop; the rear-guard.<br><br>2. The end; the tail; the train behind.<br><br>3. The latter part.',
  },
  'Reascend': {
    'id': 43507,
    'definition': '<b>REASCEND\'</b>, <i>v.i.</i> [re and ascend.] To rise, mount or climb again.<br><br><b>REASCEND\'</b>, <i>v.t.</i> To mount or ascend again.<br><br>He mounts aloft and reascends the skies.',
  },
