  'Reconquer': {
    'id': 43793,
    'definition': '<b>RECONQUER</b>, <i>v.t.</i> recon\'ker. [re and conquer.]<br><br>1. To conquer again; to recover by conquest.<br><br>2. To recover; to regain.',
  },
