  'Reconsolate': {
    'id': 43804,
    'definition': '<b>RECON\'SOLATE</b>, <i>v.t.</i> To console or comfort again. [Not in use.]',
  },
  'Reconvene': {
    'id': 43805,
    'definition': '<b>RECONVE\'NE</b>, <i>v.t.</i> [re and convene.] To convene or call together again.<br><br><b>RECONVE\'NE</b>, <i>v.i.</i> To assemble or come together again.',
  },
  'Reconvened': {
    'id': 43806,
    'definition': '<b>RECONVE\'NED</b>, <i>pp.</i> Assembled anew.',
  },
  'Reconvening': {
    'id': 43807,
    'definition': '<b>RECONVE\'NING</b>, <i>ppr.</i> Assembling anew.',
  },
  'Reconversion': {
    'id': 43808,
    'definition': '<b>RECONVER\'SION</b>, <i>n.</i> [re and conversion.] A second conversion.',
  },
  'Reconvert': {
    'id': 43809,
    'definition': '<b>RECONVERT\'</b>, <i>v.t.</i> [re and convert.] To convert again.',
  },
  'Reconverted': {
    'id': 43810,
    'definition': '<b>RECONVERT\'ED</b>, <i>pp.</i> Converted again.',
  },
  'Reconverting': {
