  'Savorly': {
    'id': 46648,
    'definition': '<b>SA\'VORLY</b>, <i>a.</i> Well seasoned; of good taste.<br><br><b>SA\'VORLY</b>, <i>adv.</i> With a pleasing relish.',
  },
  'Savory': {
    'id': 46649,
    'definition': '<b>SA\'VORY</b>, <i>a.</i> [from savor.] Pleasing to the organs of smell or taste; as a savory odor.<br><br>Make me savory meat. Gen 27.<br><br><b>SA\'VORY</b>, <i>n.</i> A plant of the genus Satureia.',
