  'Scaturiginous': {
    'id': 46791,
    'definition': '<b>SCATURIG\'INOUS</b>, <i>a.</i> [L. scaturigo.] Abounding with springs. [Not used.]',
  },
  'Scaup': {
    'id': 46792,
    'definition': '<b>SCAUP</b>, <i>n.</i> A fowl of the duck kind.',
