  'Sea-Colewort': {
    'id': 47165,
    'definition': '<b>SE\'A-COLEWORT</b>, <i>n.</i> Sea-cale, which see.',
  },
  'Sea-Compass': {
    'id': 47166,
    'definition': '<b>SE\'A-COMPASS</b>, <i>n.</i> [sea and campass.] The mariner\'s card and needle; the compass constructed for use at sea.',
  },
  'Sea-Coot': {
    'id': 47167,
    'definition': '<b>SE\'A-COOT</b>, <i>n.</i> [sea and coot.] A sea fowl,<br><br><b>SE\'A- COR\'MORANT</b>, <i>n.</i> [sea and cormorant.] The sea-crow or sea-drake.',
  },
  'Sea-Cow': {
    'id': 47168,
    'definition': '<b>SE\'A-COW</b>, <i>n.</i> [sea and cow.] The Trichecus manatus, <i>or</i> manati. [See <a href="dict://Manati">Manati</a>.]',
  },
  'Sea-Crow': {
    'id': 47169,
    'definition': '<b>SE\'A-CROW</b>, <i>n.</i> [sea and crow.] A fowl of the full kind; the mire-crow or pewet.',
  },
  'Sea-Devil': {
    'id': 47170,
    'definition': '<b>SE\'A-DEVIL</b>, <i>n.</i> [sea and devil.] The fishing frog or toad-fish, of the genus Lophius; a fish of a deformed shape, resembling a tadpole, growing to a large size, with a head larger than the whole body.',
  },
  'Sea-Dog': {
    'id': 47171,
    'definition': '<b>SE\'A-DOG</b>, <i>n.</i> [sea and dog.]<br><br>1. A fish, perhaps the shark.<br><br>2. The sea-calf or common seal.',
  },
  'Sea-Dragon': {
    'id': 47172,
    'definition': '<b>SE\'A-DRAGON</b>, <i>n.</i> [sea and dragon.] A marine monster caught in England in 1749, resembling in some degree an alligator, but having two large fins which served for swimming or flying, It had two legs terminating in hoofs, like those of an ass. Its body was covered with impenetrable scales, and it had five rows of teeth.',
  },
  'Sea-Ear': {
    'id': 47173,
    'definition': '<b>SE\'A-EAR</b>, <i>n.</i> [sea and ear.] A sea plant.',
  },
  'Sea-Eel': {
    'id': 47174,
    'definition': '<b>SE\'A-EEL</b>, <i>n.</i> [sea and eel.] An eel caught in salt water; the conger.',
  },
  'Sea-Encircled': {
    'id': 47175,
    'definition': '<b>SEA-ENCIR\'CLED</b>, <i>a.</i> [sea and encircled.] Encompassed by the sea.',
  },
  'Sea-Farer': {
    'id': 47176,
    'definition': '<b>SE\'A-FARER</b>, <i>n.</i> [sea and fare.] One that follows the seas; a mariner.',
  },
  'Sea-Faring': {
    'id': 47177,
    'definition': '<b>SE\'A-FARING</b>, <i>a.</i> Following the business of a seaman; customarily employed in navigation.',
  },
  'Sea-Fennel': {
    'id': 47178,
    'definition': '<b>SE\'A-FENNEL</b>, <i>n.</i> [sea and fennel.] The sea as samphire.',
  },
  'Sea-Fight': {
    'id': 47179,
    'definition': '<b>SE\'A-FIGHT</b>, <i>n.</i> [sea and fight.] An engagement between ships at sea; a naval action.',
  },
  'Sea-Fish': {
    'id': 47180,
    'definition': '<b>SE\'A-FISH</b>, <i>n.</i> [sea and fish.] Any marine fish; any fish that lives usually in salt water.',
  },
  'Sea-Fowl': {
