  'Sea-Gown': {
    'id': 47188,
    'definition': '<b>SE\'A-GOWN</b>, <i>n.</i> [sea and gown.] A gown or garment with short sleeves, worn by mariners.',
  },
  'Sea-Grass': {
    'id': 47189,
    'definition': '<b>SE\'A-GR\'ASS</b>, <i>[sea</i> and grass.] A plant growing on the sea shore; an aquatic plant of the genus Ruppia.',
  },
  'Sea-Green': {
    'id': 47190,
    'definition': '<b>SE\'A-GREEN</b>, <i>a.</i> [sea and green.] Having the color of sea water; being of a faint green color.<br><br><b>SE\'A-GREEN</b>, <i>n.</i><br><br>1. The color of the sea water.<br><br>2. A plant, the saxifrage.',
  },
  'Sea-Gull': {
    'id': 47191,
    'definition': '<b>SE\'A-GULL</b>, <i>n.</i> [sea and gull.] A fowl of the genus Larus; a species of gull; called also sea-crow.',
  },
  'Sea-Hare': {
    'id': 47192,
    'definition': '<b>SE\'A-HARE</b>, <i>n.</i> [sea and hare.] A marine animal of the genus Laplysia, whose body is covered with membranes reflected; it has lateral pore on the right side, and four feelers resembling ears. The body is nearly oval, soft, gelatinous and punctated. Its juice poisonous, and ir is so fetid as to cause nausea.',
  },
  'Sea-Hedghog': {
    'id': 47193,
    'definition': '<b>SEA-HEDGHOG</b>, <i>n.</i> A sea shell, a species of Echinus, so called from its prickles, which resemble in some measure those of the hedghog or urchin.',
  },
  'Sea-Hen': {
    'id': 47194,
    'definition': '<b>SE\'A-HEN</b>, <i>n.</i> [sea and hen.] Anothe name of the guillemot.',
  },
  'Sea-Hog': {
    'id': 47195,
    'definition': '<b>SE\'A-HOG</b>, <i>n.</i> [sea and hog.] The porpes, which see.',
  },
  'Sea-Holly': {
    'id': 47196,
    'definition': '<b>SE\'A-HOLLY</b>, <i>n.</i> [sea and holly.] A plant of the genus Eryngium.',
  },
  'Sea-Holm': {
    'id': 47197,
    'definition': '<b>SE\'A-HOLM</b>, <i>n.<br><br></i> 1. A small uninhabited isle.<br><br>2. Sea-holly.',
  },
  'Sea-Horse': {
    'id': 47198,
    'definition': '<b>SE\'A-HORSE</b>, <i>n.</i> [sea and horse.]<br><br>1. In ichthyoilogy, <i>the</i> morse, a species of Trichechus or walrus.<br><br>2. The hippopotamus, or river horse.<br><br>3. A fish of the needle-fish kind, four or five inches in length, ane half an inch in diameter.<br><br>4. A fish of the genus Syngnathus.',
  },
  'Sea-Legs': {
    'id': 47199,
    'definition': '<b>SE\'A-LEGS</b>, <i>n.</i> [sea and leg.] The ability to walk on a ship\' deck when pitching or rolling.',
  },
  'Sea-Lemon': {
    'id': 47200,
    'definition': '<b>SE\'A-LEMON</b>, <i>n.</i> [sea and lemon] A marine animal of the genus Doris, having an oval body, convex, marked with numerous punctures, and of a lemon color.',
  },
  'Sea-Like': {
    'id': 47201,
    'definition': '<b>SE\'A-LIKE</b>, <i>a.</i> [sea and like] Resembling the sea.',
  },
  'Sea-Lion': {
