  },
  'Sea-Pheasant': {
    'id': 47220,
    'definition': '<b>SE\'A-PHEASANT</b>, <i>n.</i> [sea and pheasant.] The pin-tailed duck.',
  },
  'Sea-Pie': {
    'id': 47221,
    'definition': '<b>SE\'A-PIE</b>, <i>n.</i> [sea and pie, <i>pica.]</i> A fowl of the genus Haematopus, and grallic order; called',
  },
  'Sea-Piece': {
    'id': 47222,
    'definition': '<b>SE\'A-PIECE</b>, <i>n.</i> [sea and piece.] A picture representing a scene at sea.',
  },
  'Sea-Plant': {
