    'definition': '<b>SE\'A-PLANT</b>, <i>n.</i> [sea and plant.] A plant that grows in salt water, as the fucus, <i>conferva</i> &c.',
  },
  'Sea-Pool': {
    'id': 47224,
    'definition': '<b>SE\'A-POOL</b>, <i>n.</i> [sea and pool.] A lake of salt water.',
  },
  'Sea-Pye': {
    'id': 47225,
    'definition': '<b>SE\'A-PYE</b>, <i>also</i> the oyster-catcher, from its thrusting its beak into oysters when open, and taking out the animal.<br><br><b>SE\'A-PIE</b>, <i>n.</i> [sea and pie.] A dish of food consisting of paste and meat boiled together; so named because common at sea.',
  },
  'Sea-Resembling': {
    'id': 47226,
    'definition': '<b>SEA-RESEM\'BLING</b>, <i>a.</i> Like the sea; sea-like.',
  },
  'Sea-Risk': {
    'id': 47227,
    'definition': '<b>SE\'A-RISK</b>, <i>n.</i> [sea and risk.] Hazard or risk at sea; danger of injury or destruction by the sea.',
  },
  'Sea-Robber': {
    'id': 47228,
    'definition': '<b>SE\'A-ROBBER</b>, <i>n.</i> [sea and robber.] A pirate; one that robs on the high seas.',
  },
  'Sea-Rocket': {
    'id': 47229,
    'definition': '<b>SE\'A-ROCKET</b>, <i>n.</i> A plant of the genus Bunias.',
  },
  'Sea-Room': {
    'id': 47230,
    'definition': '<b>SE\'A-ROOM</b>, <i>n..[sea</i> and room.] Ample space or distance from land, shoals or rocks, sufficient for a ship to drive or scud without danger of shipwreck.',
  },
  'Sea-Rover': {
    'id': 47231,
    'definition': '<b>SE\'A-ROVER</b>, <i>n.</i> [sea and rover.]<br><br>1. A pirate; one that cruizes for plunder.<br><br>2. A ship or vessel that is employed in cruizing for plunder.',
  },
  'Sea-Ruff': {
