  },
  'Semblant': {
    'id': 47619,
    'definition': '<b>SEM\'BLANT</b>, <i>n.</i> Show; figure; resemblance. [Not in use.]<br><br><b>SEM\'BLANT</b>, <i>a.</i> Like; resembling. [Not in use.]',
  },
  'Semblative': {
    'id': 47620,
    'definition': '<b>SEM\'BLATIVE</b>, <i>a.</i> Resembling; fit; suitable; according to.<br><br>And all is semblativea woman\'s part. Shak. [Not in use.]',
  },
