  'Silicicalce': {
    'id': 48582,
    'definition': '<b>SILICICAL\'CE</b>, <i>n.</i> [L. silex or silica and calx.] A mineral of the silicious kind, occurring in amorphous masses; its color is gray or brown.',
  },
  'Siliciferous': {
    'id': 48583,
    'definition': '<b>SILICIF\'EROUS</b>, <i>a.</i> [L. silex and fero, to produce.] Producing silex; or united with a portion of silex.',
  },
  'Silicify': {
    'id': 48584,
    'definition': '<b>SIL\'ICIFY</b>, <i>v.</i> t. [L. silex, flint, and facio, to make.] To convert into silex. The specimens found near Philadelphia are completely silicified.<br><br><b>SIL\'ICIFY</b>, <i>v.</i> i. To become silex.',
  },
  'Silicimurite': {
    'id': 48585,
    'definition': '<b>SILICIMU\'RITE</b>, <i>n.</i> An earth composed of silex and magnesia.',
