  'Silicle': {
    'id': 48589,
    'definition': '<b>SIL\'ICE,SIL\'ICULE, SIL\'ICLE</b>, <i>n.</i> [L. silicula, a little husk.] In botany, a little pod or bivalvular pericarp, with seeds attached to both sutures.',
  },
  'Siliculous': {
    'id': 48590,
    'definition': '<b>SILIC\'ULOUS</b>, <i>a.</i> Havin silicles or little pods, or pertaining to them.',
