  'Smaragdine': {
    'id': 49118,
    'definition': '<b>SMARAG\'DINE</b>, <i>a.</i> [L. Smaragdinus.] Pertaining to emerald; consisting of emerald, or resembling it; of an emerald green.',
  },
  'Smaragdite': {
    'id': 49119,
    'definition': '<b>SMARAG\'DITE</b>, <i>n.</i> A mineral; called also green diallage.',
