  'Spinal': {
    'id': 49991,
    'definition': '<b>SPI\'NAL</b>, <i>a.</i> [See <a href="dict://Spine">Spine</a>.] Pertaining to the spine or back bone of an animal; as the spinal marrow; spinal muscles; spinal arteries.',
  },
  'Spindle': {
    'id': 49992,
    'definition': '<b>SPIN\'DLE</b>, <i>a.</i> [See <a href="dict://Spin">Spin</a>.]<br><br>1. The pin used in spinning wheels for twisting the thread, and on which the thread when twisted, is wound.<br><br>2. A slender pointed rod or pin on which any thing turn; as the spindle of a vane.<br><br>3. The fusee of a watch.<br><br>4. A long slender stalk.<br><br>5. The lower end of a capstan, shod with iron; the pivot.<br><br><b>SPIN\'DLE</b>, <i>v.i.</i> To shoot or grow in a long slender stalk or body.',
  },
  'Spindle-Legs': {
    'id': 49993,
    'definition': '<b>SPIN\'DLE-LEGS, SPIN\'DLE-SHANKS</b>, <i>n.</i> A tall slender person; in contempt.',
  },
  'Spindle-Shanked': {
    'id': 49994,
    'definition': '<b>SPIN\'DLE-SHANKED</b>, <i>a.</i> Having long slender legs.',
