  'Spinner': {
    'id': 50007,
    'definition': '<b>SPIN\'NER</b>, <i>n.<br><br></i> 1. One that spins; one skilled in spinning.<br><br>2. A spider.',
  },
  'Spinning': {
    'id': 50008,
    'definition': '<b>SPIN\'NING</b>, <i>ppr.</i> Drawing out and twisting into threads; drawing out; delaying.<br><br><b>SPIN\'NING</b>, <i>n.<br><br></i> 1. The act, practice or art of drawing out and twisting into threads, as wool, flax and cotton.<br><br>2. The act or practice of forming webs, as spiders.',
  },
  'Spinning-Jenny': {
    'id': 50009,
    'definition': '<b>SPIN\'NING-JENNY</b>, <i>n.</i> An engine or complicated machine for spinning wool or cotton, in the manufacture of cloth.',
  },
  'Spinolet': {
    'id': 50010,
    'definition': '<b>SPIN\'OLET</b>, <i>n.</i> A small bird of the lark kind.',
