  'Stamper': {
    'id': 50458,
    'definition': '<b>STAMPER</b>, <i>n.</i> An instrument for pounding or stamping.',
  },
  'Stamping': {
    'id': 50459,
    'definition': '<b>STAMPING</b>, <i>ppr.</i> Impressing with a mark or figure; coining; imprinting.',
  },
  'Stamping-Mill': {
    'id': 50460,
    'definition': '<b>STAMPING-MILL</b>, <i>n.</i> An engine used in tin works for breaking or bruising ore.',
