  'Swartish': {
    'id': 52341,
    'definition': '<b>SWART\'ISH</b>, <i>a.</i> Somewhat dark or tawny.',
  },
  'Swarty': {
    'id': 52342,
    'definition': '<b>SWART\'Y</b>, <i>a.</i> Swarthy; tawny.',
