    'definition': '<b>TRI\'REME</b>, <i>n.</i> [L. triremis; tres and remus.] A galley or vessel with three benches or ranks of oars on a side.',
  },
  'Trirhomboidal': {
    'id': 54808,
    'definition': '<b>TRIRHOMBOID\'AL</b>, <i>a.</i> [tri and rhomboidal.] Having the form of three rhombs.',
  },
  'Trisacramentarian': {
    'id': 54809,
    'definition': '<b>TRISACRAMENTA\'RIAN</b>, <i>n.</i> [L. tres, three, and sacrament.]<br><br>One of a religious sect who admit of three sacraments and no more.',
  },
  'Trisagion': {
    'id': 54810,
    'definition': '<b>TRISAG\'ION</b>, <i>n.</i> [Gr. three, and holy.] A hymn in which the word holy is repeated three times.',
  },
  'Trisect': {
    'id': 54811,
    'definition': '<b>TRISECT\'</b>, <i>v.t.</i> [L. tres, three, and seco, to cut.] To cut or divide into three equal parts.',
  },
  'Trisected': {
