    'definition': '<b>UNADJUDG\'ED</b>, <i>a.</i> Not adjudged; not judicially decided.',
  },
  'Unadjusted': {
    'id': 55457,
    'definition': '<b>UNADJUST\'ED</b>, <i>a.</i><br><br>1. Not adjusted; not settled; not regulated; as differences unadjusted.<br><br>2. Not settled; not liquidated; as unadjusted accounts.',
  },
  'Unadministered': {
