  'Unadvisable': {
    'id': 55469,
    'definition': '<b>UNADVI\'SABLE</b>, <i>a.</i> s as z. Not advisable; not to be recommended; not expedient; not prudent.',
  },
  'Unadvised': {
    'id': 55470,
    'definition': '<b>UNADVI\'SED</b>, <i>a.</i> s as z.<br><br>1. Not prudent; not discrete.<br><br>2. Done without due consideration; rash; as an unadvised measure or proceeding.',
  },
  'Unadvisedly': {
