  'Unallayed': {
    'id': 55494,
    'definition': '<b>UNALLA\'YED</b>, <i>a.<br><br></i> 1. Not allayed; not appeased or quieted.<br><br>2. For unalloyed.',
  },
  'Unalleviated': {
