  'Unapt': {
    'id': 55562,
    'definition': '<b>UNAPT\'</b>, <i>a.</i><br><br>1. Not apt; not ready or propense.<br><br>A soldier, unapt to weep.<br><br>2. Dull; not ready to learn.<br><br>3. Unfit; not qualified; not disposed; with to, before a verb, and for, before a noun; as unapt to admit a conference with reason.<br><br>Unapt for noble, wise, spiritual employments.<br><br>4. Improper; unsuitable.',
  },
  'Unaptly': {
    'id': 55563,
    'definition': '<b>UNAPT\'LY</b>, <i>adv.</i> Unfitly; improperly.',
