  'Unaptness': {
    'id': 55564,
    'definition': '<b>UNAPT\'NESS</b>, <i>n.<br><br></i> 1. Unfitness; unsuitableness.<br><br>2. Dullness; want of quick apprehension.<br><br>3. Unreadiness; disqualification; want of propension. The mind, by excess of exertion, gets an unaptness to vigorous attempts.',
  },
  'Unargued': {
    'id': 55565,
    'definition': '<b>UN\'ARGUED</b>, <i>a.<br><br></i> 1. Not argued; not debated.<br><br>2. Not disputed; not opposed by argument.<br><br>3. Not censured; a Latinism. [Not used.]',
  },
  'Unarm': {
    'id': 55566,
    'definition': '<b>UN\'ARM</b> v.t. To disarm; to strip of armor or arms. [Not used. See <a href="dict://Disarm">Disarm</a>.]',
  },
