  'Unbarring': {
    'id': 55646,
    'definition': '<b>UNB\'ARRING</b>, <i>ppr.</i> Removing the bars from; unfastening.',
  },
  'Unbashful': {
    'id': 55647,
    'definition': '<b>UNBASH\'FUL</b>, <i>a.</i> Not bashful; bold; impudent.',
  },
  'Unbated': {
    'id': 55648,
    'definition': '<b>UNBA\'TED</b>, <i>a.</i> Not repressed; not blunted. [Not in use.]',
  },
  'Unbathed': {
    'id': 55649,
    'definition': '<b>UNBA\'THED</b>, <i>a.</i> Not bathed; not wet.',
  },
  'Unbattered': {
    'id': 55650,
    'definition': '<b>UNBAT\'TERED</b>, <i>a.</i> Not battered; not bruised or injured by blows.',
  },
  'Unbay': {
    'id': 55651,
    'definition': '<b>UNBA\'Y</b>, <i>v.t.</i> To open; to free from the restraint of mounds.<br><br>I ought to unbay the current of my passions. [Not in use.]',
  },
  'Unbearded': {
    'id': 55652,
    'definition': '<b>UNBEARDED</b>, <i>a.</i> unberd\'ed. Having no beard; beardless.',
  },
  'Unbearing': {
    'id': 55653,
    'definition': '<b>UNBEARING</b>, <i>a.</i> Bearing or producing no fruit.',
  },
  'Unbeaten': {
    'id': 55654,
    'definition': '<b>UNBE\'ATEN</b>, <i>a.<br><br></i> 1. Not beaten; not treated with blows.<br><br>2. Untrod; not beaten by the feet; as unbeaten paths.',
  },
  'Unbeauteous': {
    'id': 55655,
    'definition': '<b>UNBEAU\'TEOUS,<br><br>UNBEAU\'TIFUL</b>, <i>a.</i> [See <a href="dict://Beauty">Beauty</a>.] Not beautiful; having no beauty.',
  },
  'Unbecome': {
    'id': 55656,
    'definition': '<b>UNBECOME</b>, <i>v.t.</i> Not to become; not to be suitable to; to misbecome. [Not used.]',
  },
  'Unbecoming': {
    'id': 55657,
    'definition': '<b>UNBECOMING</b>, <i>a.</i> Unsuitable; improper for the person or character; indecent; indecorous.<br><br>My grief lets unbecoming speeches fall.',
  },
  'Unbecomingly': {
    'id': 55658,
    'definition': '<b>UNBECOMINGLY</b>, <i>adv.</i> In an unsuitable manner; indecorously.',
  },
  'Unbecomingness': {
    'id': 55659,
    'definition': '<b>UNBECOMINGNESS</b>, <i>n.</i> Unsuitableness to the person, character or circumstances; impropriety; indecorousness.',
  },
  'Unbed': {
    'id': 55660,
    'definition': '<b>UNBED\'</b>, <i>v.t.</i> To raise or rouse from bed.<br><br>Eels unbed themselves and stir at the noise of thunder.',
  },
  'Unbedded': {
    'id': 55661,
    'definition': '<b>UNBED\'DED</b>, <i>pp.</i> Raised from bed; disturbed.',
  },
  'Unbedding': {
    'id': 55662,
    'definition': '<b>UNBED\'DING</b>, <i>ppr.</i> Raising from bed.',
  },
  'Unbefitting': {
    'id': 55663,
    'definition': '<b>UNBEFIT\'TING</b>, <i>a.</i> Not befitting; unsuitable; unbecoming.',
  },
  'Unbefriended': {
    'id': 55664,
    'definition': '<b>UNBEFRIENDED</b>, <i>a.</i> unbefrend\'ed. Not befriended; not supported by friends; having no friendly aid.',
  },
  'Unbeget': {
    'id': 55665,
    'definition': '<b>UNBEGET\'</b>, <i>v.t.</i> To deprive of existence.',
  },
  'Unbegot': {
    'id': 55666,
    'definition': '<b>UNBEGOT\'<br><br>UNBEGOT\'TEN</b>, <i>a.<br><br></i> 1. Not generated; eternal.<br><br>2. Not yet generated.<br><br>3. Not begotten; not generated.',
  },
  'Unbeguile': {
    'id': 55667,
    'definition': '<b>UNBEGUI\'LE</b>, <i>v.t.</i> To undeceive; to free from the influence of deceit.<br><br>Then unbeguile thyself.',
  },
  'Unbeguiled': {
    'id': 55668,
    'definition': '<b>UNBEGUI\'LED</b>, <i>pp.</i> Undeceived.',
  },
  'Unbegun': {
    'id': 55669,
    'definition': '<b>UNBEGUN\'</b>, <i>a.</i> Not begun.',
  },
  'Unbeheld': {
    'id': 55670,
    'definition': '<b>UNBEHELD\'</b>, <i>a.</i> Not beheld; not seen; not visible.',
  },
  'Unbeing': {
    'id': 55671,
    'definition': '<b>UNBE\'ING</b>, <i>a.</i> Not existing. [Not in use.]',
  },
  'Unbelief': {
    'id': 55672,
    'definition': '<b>UNBELIE\'F</b>, <i>n.</i><br><br>1. Incredulity; the withholding of belief; as, unbelief is blind.<br><br>2. Infidelity; disbelief of divine revelation.<br><br>3. In the New Testament, disbelief of the truth of the gospel, rejection of Christ as the Savior of men, and of the doctrines he taught; distrust of God\'s promises and faithfulness, &c. Mat 13. Mark 16. Heb 3. Rom 4.<br><br>4. Weak faith. Mark 9.',
  },
  'Unbelieve': {
    'id': 55673,
    'definition': '<b>UNBELIE\'VE</b>, <i>v.t.<br><br></i> 1. To discredit; not to believe or trust.<br><br>2. Not to think real or true.',
  },
  'Unbelieved': {
    'id': 55674,
    'definition': '<b>UNBELIE\'VED</b>, <i>pp.</i> Not believed; discredited.',
  },
  'Unbeliever': {
    'id': 55675,
    'definition': '<b>UNBELIE\'VER</b>, <i>n.<br><br></i> 1. An incredulous person; one who does not believe.<br><br>2. An infidel; one who discredits revelation, or the mission, character and doctrines of Christ. 2 Cor 6.',
  },
  'Unbelieving': {
    'id': 55676,
    'definition': '<b>UNBELIE\'VING</b>, <i>a.<br><br></i> 1. Not believing; incredulous.<br><br>2. Infidel; discrediting divine revelation, or the mission, character and doctrines of Christ; as the unbelieving Jews. Acts 14. Rev 21.',
  },
  'Unbeloved': {
    'id': 55677,
    'definition': '<b>UNBELOVED</b>, <i>a.</i> Not loved.',
  },
  'Unbemoaned': {
    'id': 55678,
    'definition': '<b>UNBEMOANED</b>, <i>a.</i> Not lamented.',
  },
  'Unbend': {
    'id': 55679,
    'definition': '<b>UNBEND\'</b>, <i>v.t.<br><br></i> 1. To free from flexure; to make straight; as, to unbend a bow.<br><br>2. To relax; to remit from a strain or from exertion; to set at ease for a time; as, to unbend the mind from study or care.<br><br>3. To relax effeminately.<br><br>You unbend your noble strength.<br><br>4. In seamanship, to take the sails from their yards and stays; also, to cast loose a cable from the anchors; also, to untie one rope from another.',
  },
  'Unbending': {
    'id': 55680,
    'definition': '<b>UNBEND\'ING</b>, <i>ppr.<br><br></i> 1. Relaxing from any strain; remitting; taking from their yards, &c., as sails.<br><br>2. a. Not suffering flexure.<br><br>3. Unyielding; resolute; inflexible; applied to persons.<br><br>4. Unyielding; inflexible; firm; applied to things; as unbending truth.<br><br>5. Devoted to relaxation.<br><br>I hope it may entertain your lordship at an unbending hour.',
  },
  'Unbeneficed': {
    'id': 55681,
    'definition': '<b>UNBEN\'EFICED</b>, <i>a.</i> Not enjoying or having a benefice.',
  },
  'Unbenevolent': {
    'id': 55682,
    'definition': '<b>UNBENEV\'OLENT</b>, <i>a.</i> Not benevolent; not kind.',
  },
  'Unbenighted': {
    'id': 55683,
    'definition': '<b>UNBENIGHTED</b>, <i>a.</i> Never visited by darkness.',
  },
  'Unbenign': {
    'id': 55684,
    'definition': '<b>UNBENIGN</b>, <i>a.</i> Not benign; not favorable or propitious; malignant.',
  },
  'Unbent': {
    'id': 55685,
    'definition': '<b>UNBENT\'</b>, <i>pp.</i> of unbend.<br><br>1. Relaxed; remitted; relieved from strain or exertion.<br><br>2. In seamen\'s language, taken from the yards; loosed; as, the sails are unbent; the cable is unbent.<br><br>3. Not strained; unstrung; as a bow unbent.<br><br>4. Not crushed; not subdued; as, the soul is unbent by woes.',
  },
  'Unbequeathed': {
    'id': 55686,
    'definition': '<b>UNBEQUE\'ATHED</b>, <i>a.</i> Not bequeathed; not given by legacy.',
  },
  'Unbeseeming': {
    'id': 55687,
    'definition': '<b>UNBESEE\'MING</b>, <i>a.</i> Unbecoming; not befitting unsuitable.',
  },
  'Unbesought': {
