  'Unbookish': {
    'id': 55735,
    'definition': '<b>UNBOOK\'ISH</b>, <i>a.</i><br><br>1. Not addicted to books or reading.<br><br>2. Not cultivated by erudition.',
  },
  'Unborn': {
    'id': 55736,
    'definition': '<b>UNBORN\',<br><br>UN\'BORN</b>, <i>a.</i> [It is accented either on the first or second syllable.] Not born; not brought into life; future.<br><br>Some unborn sorrow, ripe in fortune\'s womb.<br><br>The woes to come, the children yet unborn shall feel this day.',
  },
  'Unborrowed': {
    'id': 55737,
    'definition': '<b>UNBOR\'ROWED</b>, <i>a.</i> Not borrowed; genuine; original; native; one\'s own; as unborrowed beauties; unborrowed gold; unborrowed excellence.',
  },
  'Unbosom': {
    'id': 55738,
    'definition': '<b>UNBOSOM</b>, <i>v.t.</i> s as z.<br><br>1. To disclose freely one\'s secret opinions or feelings.<br><br>2. To reveal in confidence.',
  },
  'Unbosomed': {
    'id': 55739,
    'definition': '<b>UNBOSOMED</b>, <i>pp.</i> Disclosed, as secrets; revealed in confidence.',
  },
  'Unbosoming': {
    'id': 55740,
    'definition': '<b>UNBOSOMING</b>, <i>ppr.</i> Disclosing, as secrets; revealing in confidence.',
  },
  'Unbottomed': {
    'id': 55741,
    'definition': '<b>UNBOT\'TOMED</b>, <i>a.<br><br></i> 1. Having no bottom; bottomless.<br><br>The dark, unbottom\'d, infinite abyss.<br><br>2. Having no solid foundation.',
  },
  'Unbought': {
    'id': 55742,
    'definition': '<b>UNBOUGHT</b>, <i>a.</i> unbaut\'.<br><br>1. Not bought; obtained without money or purchase.<br><br>The unbought dainties of the poor.<br><br>2. Not having a purchaser.',
  },
  'Unbound': {
    'id': 55743,
    'definition': '<b>UNBOUND\'</b>, <i>a.<br><br></i> 1. Not bound; loose; wanting a cover; as unbound books.<br><br>2. Not bound by obligation or covenant.<br><br>3. pret. of unbind.',
  },
  'Unbounded': {
    'id': 55744,
    'definition': '<b>UNBOUND\'ED</b>, <i>a.<br><br></i> 1. Having no bound or limit; unlimited in extent; infinite; interminable; as unbounded space; unbounded power.<br><br>2. Having no check or control; unrestrained. The young man has unbounded license. His extravagance is unbounded.',
  },
  'Unboundedly': {
    'id': 55745,
    'definition': '<b>UNBOUND\'EDLY</b>, <i>adv.</i> Without bounds or limits.',
  },
  'Unboundedness': {
    'id': 55746,
    'definition': '<b>UNBOUND\'EDNESS</b>, <i>n.</i> Freedom from bounds or limits.',
  },
  'Unbounteous': {
    'id': 55747,
    'definition': '<b>UNBOUN\'TEOUS</b>, <i>a.</i> Not bounteous; not liberal.',
  },
  'Unbow': {
