  'Uncial': {
    'id': 55860,
    'definition': '<b>UN\'CIAL</b>, <i>a.</i> [L. uncialis.] Pertaining to letters of a large size, used in ancient manuscripts.<br><br><b>UN\'CIAL</b>, <i>n.</i> An uncial letter.',
  },
  'Uncinate': {
    'id': 55861,
    'definition': '<b>UN\'CINATE</b>, <i>a.</i> [L. uncinatus, from uncus, a hook.] In botany, hooked at the end.',
