  'Uncircumcision': {
    'id': 55863,
    'definition': '<b>UNCIRCUMCI\'SION</b>, <i>n.</i> Absence or want of circumcision.',
  },
  'Uncircumscribed': {
    'id': 55864,
    'definition': '<b>UNCIRCUMSCRI\'BED</b>, <i>a.</i> Not circumscribed; not bounded; not limited.<br><br>Where the prince is uncircumscribed, obedience ought to be unlimited.',
  },
  'Uncircumspect': {
    'id': 55865,
    'definition': '<b>UNCIR\'CUMSPECT</b>, <i>a.</i> Not circumspect; not cautious.',
