  'Uncircumstantial': {
    'id': 55866,
    'definition': '<b>UNCIRCUMSTAN\'TIAL</b>, <i>a.</i> Not important. [Not in use.]',
  },
  'Uncivil': {
    'id': 55867,
    'definition': '<b>UNCIV\'IL</b>, <i>a.</i><br><br>1. Not civil; not complaisant; not courteous in manners; applied to persons.<br><br>2. Not polite; rude; applied to manners; as uncivil behavior.',
  },
  'Uncivilization': {
    'id': 55868,
    'definition': '<b>UNCIVILIZA\'TION</b>, <i>n.</i> A state of savageness; rude state.',
  },
  'Uncivilized': {
    'id': 55869,
    'definition': '<b>UNCIV\'ILIZED</b>, <i>a.<br><br></i> 1. Not reclaimed from savage life; as the uncivilized inhabitants of Canada or New Zealand.<br><br>2. Coarse; indecent; as he most uncivilized words in our language. [Not in use.]',
  },
  'Uncivilly': {
    'id': 55870,
    'definition': '<b>UNCIV\'ILLY</b>, <i>adv.</i> Not complaisantly; not courteously; rudely.',
  },
  'Unclad': {
    'id': 55871,
    'definition': '<b>UNCLAD\'</b>, <i>a.</i> Not clad; not clothed.',
  },
  'Unclaimed': {
    'id': 55872,
    'definition': '<b>UNCLA\'IMED</b>, <i>a.</i> Not claimed; not demanded; not called for; as unclaimed dividends of a bank.',
  },
  'Unclarified': {
    'id': 55873,
    'definition': '<b>UNCLAR\'IFIED</b>, <i>a.</i> Not purified; not fined; not departed by a separation of feculent or foreign matter.',
  },
  'Unclasp': {
    'id': 55874,
    'definition': '<b>UNCL\'ASP</b>, <i>v.t.</i> To loose a clasp; to open what is fastened with a clasp; as, to unclasp a book.',
