  'Uncondensed': {
    'id': 55976,
    'definition': '<b>UNCONDENS\'ED</b>, <i>a.</i> Not condensed.',
  },
  'Unconditional': {
    'id': 55977,
    'definition': '<b>UNCONDI\'TIONAL</b>, <i>a.</i> Absolute; unreserved; not limited by any conditions. We are required to make an unconditional surrender of ourselves to our Maker. The king demanded unconditional submission.<br><br>O pass not, Lord, an absolute decree, or bind thy sentence unconditional.',
  },
  'Unconditionally': {
    'id': 55978,
    'definition': '<b>UNCONDI\'TIONALLY</b>, <i>adv.</i> Without conditions; without terms of limitation; without reservation. The troops did not surrender unconditionally, but by capitulation.',
  },
  'Unconfessed': {
    'id': 55979,
    'definition': '<b>UNCONFESS\'ED</b>, <i>a.</i> Not confessed; not acknowledged.',
  },
  'Unconfinable': {
    'id': 55980,
    'definition': '<b>UNCONFI\'NABLE</b>, <i>a.<br><br></i> 1. Unbounded. [Not used.]<br><br>2. That cannot be confined or restrained.',
  },
  'Unconfined': {
    'id': 55981,
    'definition': '<b>UNCONFI\'NED</b>, <i>a.</i><br><br>1. Not confined; free from restraint; free from control.<br><br>2. Having no limits; illimitable; unbounded.',
  },
  'Unconfinedly': {
    'id': 55982,
    'definition': '<b>UNCONFI\'NEDLY</b>, <i>adv.</i> Without confinement or limitation.',
  },
  'Unconfirmed': {
    'id': 55983,
    'definition': '<b>UNCONFIRM\'ED</b>, <i>a.<br><br></i> 1. Not fortified by resolution; weak; raw; as troops unconfirmed by experience.<br><br>2. Not confirmed; not strengthened by additional testimony.<br><br>His witness unconfirm\'d.<br><br>3. Not confirmed according to the church ritual.',
  },
  'Unconform': {
    'id': 55984,
    'definition': '<b>UNCONFORM\'</b>, <i>a.</i> Unlike; dissimilar; not analogous. [Not in use.]',
