  'Unconformable': {
    'id': 55985,
    'definition': '<b>UNCONFORM\'ABLE</b>, <i>a.</i> Not consistent; not agreeable; not conforming.<br><br>Moral evil is an action unconformable to the rule of our duty.',
  },
  'Unconformity': {
    'id': 55986,
    'definition': '<b>UNCONFORM\'ITY</b>, <i>n.</i> Incongruity; inconsistency; want of conformity.',
  },
  'Unconfused': {
    'id': 55987,
    'definition': '<b>UNCONFU\'SED</b>, <i>a.</i> s as z.<br><br>1. Free from confusion or disorder.<br><br>2. Not embarrassed.',
  },
  'Unconfusedly': {
    'id': 55988,
    'definition': '<b>UNCONFU\'SEDLY</b>, <i>adv.</i> s as z. Without confusion or disorder.',
  },
  'Unconfutable': {
    'id': 55989,
    'definition': '<b>UNCONFU\'TABLE</b>, <i>a.</i> Not confutable; not to be refuted or overthrown; that cannot be disproved or convicted of error; as an unconfutable argument.',
  },
  'Uncongealable': {
    'id': 55990,
    'definition': '<b>UNCONGE\'ALABLE</b>, <i>a.</i> Not capable of being congealed.',
  },
  'Uncongealed': {
    'id': 55991,
    'definition': '<b>UNCONGE\'ALED</b>, <i>a.</i> Not frozen; not congealed; not concreted.',
