  'Unconjugal': {
    'id': 55993,
    'definition': '<b>UNCON\'JUGAL</b>, <i>a.</i> Not suitable to matrimonial faith; not befitting a wife or husband.',
  },
  'Unconjunctive': {
    'id': 55994,
    'definition': '<b>UNCONJUNC\'TIVE</b>, <i>a.</i> That cannot be joined. [Little used.]',
  },
  'Unconnected': {
    'id': 55995,
    'definition': '<b>UNCONNECT\'ED</b>, <i>a.</i><br><br>1. Not connected; not united; separate.<br><br>2. Not coherent; not joined by proper transitions or dependence of parts; loose; vague; desultory; as an unconnected discourse.',
  },
  'Unconniving': {
    'id': 55996,
    'definition': '<b>UNCONNI\'VING</b>, <i>a.</i> Not conniving; not overlooking or winking at.',
