  'Unconquerable': {
    'id': 55997,
    'definition': '<b>UNCON\'QUERABLE</b>, <i>a.</i><br><br>1. Not conquerable; invincible; that cannot be vanquished or defeated; that cannot be overcome in contest; as an unconquerable for.<br><br>2. That cannot be subdued and brought under control; as unconquerable passions or temper.',
  },
  'Unconquerably': {
    'id': 55998,
    'definition': '<b>UNCON\'QUERABLY</b>, <i>adv.</i> Invincibly; insuperably; as foes unconquerably strong.',
  },
  'Unconquered': {
    'id': 55999,
    'definition': '<b>UNCON\'QUERED</b>, <i>a.</i><br><br>1. Not vanquished or defeated.<br><br>2. Unsubdued; not brought under control.<br><br>3. Invincible; insuperable.',
  },
  'Unconsciencious': {
    'id': 56000,
    'definition': '<b>UNCONSCIEN\'CIOUS</b>, <i>a.</i> Not consciencious; not regulated or limited by conscience.',
  },
  'Unconscionable': {
    'id': 56001,
    'definition': '<br>UNCON\'SCIONABLE, a.<br><br>1. Unreasonable; exceeding the limits of any reasonable claim or expectation; as an unconscionable request or demand.<br><br>2. Forming unreasonable expectations. You cannot be so unconscionable as to expect this sacrifice on my part.<br><br>3. Enormous; vast; as unconscionable size or strides. [Not elegant.]<br><br>4. Not guided or influenced by conscience.',
  },
  'Unconscionableness': {
    'id': 56002,
    'definition': '<b>UNCON\'SCIONABLENESS</b>, <i>n.</i> Unreasonableness of hope or claim.',
  },
  'Unconscionably': {
    'id': 56003,
    'definition': '<b>UNCON\'SCIONABLY</b>, <i>adv.</i> Unreasonably; in a manner or degree that conscience and reason do not justify.',
  },
  'Unconscious': {
    'id': 56004,
    'definition': '<b>UNCON\'SCIOUS</b>, <i>a.</i><br><br>1. Not conscious; having no mental perception; as unconscious causes.<br><br>2. Not conscious; not knowing; not perceiving; as unconscious of guilt or error.',
  },
  'Unconsciously': {
    'id': 56005,
    'definition': '<b>UNCON\'SCIOUSLY</b>, <i>adv.</i> Without perception; without knowledge.',
  },
  'Unconsciousness': {
