  'Uncontroverted': {
    'id': 56040,
    'definition': '<b>UNCON\'TROVERTED</b>, <i>a.</i> Not disputed; not contested; not liable to be called in question.',
  },
  'Unconversable': {
    'id': 56041,
    'definition': '<b>UNCONVERS\'ABLE</b>, <i>a.</i><br><br>1. Not free in conversation; not social; reserved.<br><br>2. Not suited to conversation.',
  },
  'Unconversant': {
    'id': 56042,
    'definition': '<b>UNCON\'VERSANT</b>, <i>a.</i> Not conversant; not familiarly acquainted with.',
  },
  'Unconverted': {
    'id': 56043,
    'definition': '<b>UNCONVERT\'ED</b>, <i>a.</i><br><br>1. Not converted; not changed in opinion; not turned from one faith to another.<br><br>2. Not persuaded of the truth of the christian religion; as unconverted pagans.<br><br>3. Not renewed; not regenerated; not having the natural enmity of the heart subdued, and a principle of grace implanted.<br><br>4. Not turned or changed from one form to another.',
  },
  'Unconvertible': {
    'id': 56044,
    'definition': '<b>UNCONVERT\'IBLE</b>, <i>a.</i> That cannot be converted or changed in form. Lead is unconvertible into silver.',
  },
  'Unconvinced': {
    'id': 56045,
    'definition': '<b>UNCONVIN\'CED</b>, <i>a.</i> Not convinced; not persuaded.',
  },
  'Uncord': {
