  },
  'Uncorrected': {
    'id': 56052,
    'definition': '<b>UNCORRECT\'ED</b>, <i>a.</i><br><br>1. Not corrected; not revised; not rendered exact; as an uncorrected copy of a writing.<br><br>2. Not reformed; not amended; as life or manners uncorrected.',
  },
  'Uncorrigible': {
