    'definition': '<b>UNEXIST\'ENT</b>, <i>a.</i> Not existing.',
  },
  'Unexorcised': {
    'id': 56561,
    'definition': '<b>UNEX\'ORCISED</b>, <i>a.</i> s as z. Not exorcised; not cast out by exorcism.',
  },
  'Unexpanded': {
    'id': 56562,
    'definition': '<b>UNEXPAND\'ED</b>, <i>a.</i> Not expanded not spread out.',
  },
  'Unexpectation': {
    'id': 56563,
    'definition': '<b>UNEXPECTA\'TION</b>, <i>n.</i> Want of foresight. [Not in use.]',
  },
  'Unexpected': {
    'id': 56564,
    'definition': '<b>UNEXPECT\'ED</b>, <i>a.</i> Not expected; not looked for; sudden; not provided against.',
  },
  'Unexpectedly': {
    'id': 56565,
    'definition': '<b>UNEXPECT\'EDLY</b>, <i>adv.</i> At a time or in a manner not expected or looked for; suddenly.',
  },
  'Unexpectedness': {
    'id': 56566,
    'definition': '<b>UNEXPECT\'EDNESS</b>, <i>n.</i> The quality of being unexpected, or of coming suddenly and by surprise.',
  },
  'Unexpectorating': {
    'id': 56567,
    'definition': '<b>UNEXPEC\'TORATING</b>, <i>a.</i> Not expectorating; not discharging from the throat or lungs.',
  },
  'Unexpedient': {
    'id': 56568,
    'definition': '<b>UNEXPE\'DIENT</b>, <i>a.</i> Not expedient. [But inexpedient is the word now used.]',
  },
  'Unexpended': {
    'id': 56569,
    'definition': '<b>UNEXPEND\'ED</b>, <i>a.</i> Not expended; not laid out. There is an unexpended balance of the appropriation.',
  },
  'Unexpensive': {
