    'definition': '<b>UNEXPRESS\'ED</b>, <i>a.</i> Not expressed; not mentioned or named; not exhibited.',
  },
  'Unexpressible': {
    'id': 56579,
    'definition': '<b>UNEXPRESS\'IBLE</b>, <i>a.</i> That cannot be expressed. [But inexpressible is the word now used.]',
  },
  'Unexpressive': {
    'id': 56580,
    'definition': '<b>UNEXPRESS\'IVE</b>, <i>a.<br><br></i> 1. Not having the power of expressing.<br><br>2. Inexpressible; unutterable.',
  },
  'Unextended': {
    'id': 56581,
    'definition': '<b>UNEXTEND\'ED</b>, <i>a.</i> Occupying no assignable space; having no dimensions; as a spiritual, an unextended substance.',
  },
  'Unextinct': {
    'id': 56582,
    'definition': '<b>UNEXTINCT\'</b>, <i>a.</i> Not extinct; not being destroyed; not having perished.',
  },
  'Unextinguishable': {
    'id': 56583,
    'definition': '<b>UNEXTIN\'GUISHABLE</b>, <i>a.<br><br></i> 1. That cannot be extinguished; unquenchable; as unextinguishable fire.<br><br>2. That cannot be annihilated or repressed; as an unextinguishable thirst for knowledge. [But inextinguishable is more generally used.]',
  },
  'Unextinguishably': {
    'id': 56584,
    'definition': '<b>UNEXTIN\'GUISHABLY</b>, <i>adv.</i> In a manner or degree that precludes extinction.',
  },
  'Unextinguished': {
    'id': 56585,
    'definition': '<b>UNEXTIN\'GUISHED</b>, <i>a.</i> Not extinguished; not quenched; not entirely repressed.',
  },
  'Unextirpated': {
    'id': 56586,
    'definition': '<b>UNEX\'TIRPATED</b>, <i>a.</i> Not extirpated; not rooted out.',
  },
  'Unextorted': {
