  'Unhindered': {
    'id': 56870,
    'definition': '<b>UNHIN\'DERED</b>, <i>a.</i> Not hindered; not opposed; exerting itself freely.',
  },
  'Unhinge': {
    'id': 56871,
    'definition': '<b>UNHINGE</b>, <i>v.t.</i> unhinj\'.<br><br>1. To take from the hinges; as, to unhinge a door.<br><br>2. To displace; to unfix by violence.<br><br>3. To unfix; to loosen; to render unstable or wavering; as, to unhinge the mind; to unhinge opinions.',
  },
  'Unhoard': {
    'id': 56872,
    'definition': '<b>UNHOARD</b>, <i>v.t.</i> To steal from a hoard; to scatter.',
  },
  'Unholiness': {
    'id': 56873,
    'definition': '<b>UNHO\'LINESS</b>, <i>n.<br><br></i> 1. Want of holiness; an unsanctified state of the heart.<br><br>2. Impiety; wickedness; profaneness.',
  },
  'Unholy': {
    'id': 56874,
    'definition': '<b>UNHO\'LY</b>, <i>a.</i><br><br>1. Not holy; not renewed and sanctified. 2 Tim 3.<br><br>2. Profane; not hallowed; not consecrated; common. Heb 10.<br><br>3. Impious; wicked.<br><br>4. Not ceremonially purified. Lev 10.',
  },
  'Unhonest': {
    'id': 56875,
    'definition': '<b>UNHON\'EST</b>, <i>a.</i> [See <a href="dict://Honest">Honest</a>.] Dishonest; dishonorable. Obs.',
  },
  'Unhonored': {
    'id': 56876,
    'definition': '<b>UNHON\'ORED</b>, <i>a.</i> [See <a href="dict://Honor">Honor</a>.] Not honored; not regarded with veneration; not celebrated.',
  },
  'Unhook': {
    'id': 56877,
    'definition': '<b>UNHOOK\'</b>, <i>v.t.</i> To loose from a hook.',
  },
  'Unhoop': {
    'id': 56878,
    'definition': '<b>UNHOOP\'</b>, <i>v.t.</i> To strip of hoops.',
  },
  'Unhoped': {
    'id': 56879,
    'definition': '<b>UNHO\'PED</b>, <i>a.</i> Not hoped for; not so probable as to excite hope.<br><br>With unhop\'d success.<br><br>Unhoped for, unhoped, as above.',
  },
  'Unhopeful': {
