  'Unhorsing': {
    'id': 56884,
    'definition': '<b>UNHORS\'ING</b>, <i>ppr.</i> Throwing from a horse; dismounting.',
  },
  'Unhositable': {
    'id': 56885,
    'definition': '<b>UNHOS\'ITABLE</b>, <i>a.</i> Not kind to strangers. [But inhospitable is the word now used.]',
  },
  'Unhostile': {
    'id': 56886,
    'definition': '<b>UNHOS\'TILE</b>, <i>a.</i> Not belonging to a public enemy.',
  },
  'Unhouse': {
    'id': 56887,
    'definition': '<b>UNHOUSE</b>, <i>v.t.</i> unhouz\'.<br><br>1. To drive from the house or habitation; to dislodge.<br><br>2. To deprive of shelter.',
  },
  'Unhoused': {
    'id': 56888,
    'definition': '<b>UNHOUS\'ED</b>, <i>pp.<br><br></i> 1. Driven from a house or habitation.<br><br>2. a. Wanting a house; homeless.<br><br>3. Having no settled habitation.<br><br>4. Destitute of shelter or cover. Cattle in severe weather should not be left unhoused.',
  },
  'Unhouseled': {
    'id': 56889,
    'definition': '<b>UNHOUS\'ELED</b>, <i>a.</i> s as z. Not having received the sacrament.',
  },
  'Unhuman': {
    'id': 56890,
    'definition': '<b>UNHU\'MAN</b>, <i>a.</i> Inhuman. [But inhuman is the word used.]',
  },
  'Unhumanize': {
    'id': 56891,
    'definition': '<b>UNHU\'MANIZE</b>, <i>v.t.</i> To render inhuman or barbarous.',
  },
  'Unhumbled': {
    'id': 56892,
    'definition': '<b>UNHUM\'BLED</b>, <i>a.<br><br></i> 1. Not humbled; not affected with shame or confusion; not contrite in spirit.<br><br>2. In theology, not having the will and the natural enmity of the heart to God and his law, subdued.',
  },
  'Unhung': {
