  'Unkent': {
    'id': 57040,
    'definition': '<b>UNKENT\'</b>, <i>a.</i> [un and ken, to know.] Unknown. Obs.',
  },
  'Unkept': {
    'id': 57041,
    'definition': '<b>UNKEPT\'</b>, <i>a.<br><br></i> 1. Not kept; not retained; not preserved.<br><br>2. Not observed; not obeyed; as a command.',
