  'Unkid': {
    'id': 57043,
    'definition': '<b>UNKID</b>, <i>for</i> uncouth, odd; strange. [Not in use.]',
  },
  'Unkind': {
    'id': 57044,
    'definition': '<b>UNKIND</b>, <i>a.</i><br><br>1. Not kind; not benevolent; not favorable; not obliging.<br><br>2. Unnatural.',
  },
  'Unkindly': {
    'id': 57045,
    'definition': '<b>UNKINDLY</b>, <i>a.<br><br></i> 1. Unnatural; contrary to nature; as an unkindly crime.<br><br>2. Unfavorably; malignant; as an unkindly fog.<br><br><b>UNKINDLY</b>, <i>adv.<br><br></i> 1. Without kindness; without affection; as, to treat one unkindly.<br><br>2. In a manner contrary to nature; unnaturally.<br><br>All works of nature, abortive, monstrous, or unkindly mix\'d.',
  },
  'Unkindness': {
    'id': 57046,
    'definition': '<b>UNKINDNESS</b>, <i>n.</i><br><br>1. Want of kindness; want of natural affection; want of good will.<br><br>2. Disobliging treatment; disfavor.',
