  'Unmeasured': {
    'id': 57170,
    'definition': '<b>UNMEAS\'URED</b>, <i>a.<br><br></i> 1. Not measured; plentiful beyond measure.<br><br>2. Immense; infinite; as unmeasured space.',
  },
  'Unmechanical': {
    'id': 57171,
    'definition': '<b>UNMECHAN\'ICAL</b>, <i>a.</i> Not mechanical; not according to the laws or principles of mechanics.<br><br>Unmeddled with, not meddled with; not touched; not altered.',
  },
  'Unmeddling': {
