  'Unsatisfiable': {
    'id': 57759,
    'definition': '<b>UNSAT\'ISFIABLE</b>, <i>a.</i> That cannot be satisfied.',
  },
  'Unsatisfied': {
    'id': 57760,
    'definition': '<b>UNSAT\'ISFIED</b>, <i>a.<br><br></i> 1. Not satisfied; not having enough; not filled; not gratified to the full; as unsatisfied appetites or desires.<br><br>2. Not content; not pleased; as, to be unsatisfied with the choice of an officer; to be unsatisfied with the wages or compensation allowed.<br><br>3. Not settled in opinion; not resting in confidence of the truth of any thing; as, to be unsatisfied as to the freedom of the will.<br><br>4. Not convinced or fully persuaded. The judges appeared to be unsatisfied with the evidence.<br><br>5. Not fully paid.<br><br>An execution returned unsatisfied.',
  },
  'Unsatisfiedness': {
    'id': 57761,
    'definition': '<b>UNSAT\'ISFIEDNESS</b>, <i>n.</i> The state of being not satisfied or content.',
  },
  'Unsatisfying': {
