    'definition': '<b>UNSKILL\'FULNESS</b>, <i>n.</i> Want of art or knowledge; want of that readiness in action or execution, which is acquired by use, experience and observation.',
  },
  'Unslain': {
    'id': 57897,
    'definition': '<b>UNSLA\'IN</b>, <i>a.</i> Not slain; not killed.',
  },
  'Unslaked': {
    'id': 57898,
    'definition': '<b>UNSLA\'KED</b>, <i>a.</i> Not slaked; unquenched; as unslaked thirst.<br><br><b>UNSLA\'KED</b>, <i>a.</i> Not saturated with water; as unslaked lime.',
  },
  'Unsleeping': {
