  },
  'Unsupplanted': {
    'id': 58026,
    'definition': '<b>UNSUPPLANT\'ED</b>, <i>a.</i> Not supplanted; not overthrown by secret means or stratagem.',
  },
  'Unsupplied': {
    'id': 58027,
    'definition': '<b>UNSUPPLI\'ED</b>, <i>a.</i> Not supplied; not furnished with things necessary.',
  },
  'Unsupportable': {
    'id': 58028,
    'definition': '<b>UNSUPPORTABLE</b>, <i>a.</i> That cannot be supported; intolerable. [But insupportable is generally used.]',
