  'Untrembling': {
    'id': 58152,
    'definition': '<b>UNTREM\'BLING</b>, <i>a.</i> Not trembling or shaking; firm; steady.',
  },
  'Untried': {
    'id': 58153,
    'definition': '<b>UNTRI\'ED</b>, <i>a.<br><br></i> 1. Not tried; not attempted.<br><br>2. Not yet experienced; as untried sufferings.<br><br>3. Not having passed trial; not heard and determined in law. The cause remains untried.',
  },
  'Untrimmed': {
    'id': 58154,
    'definition': '<b>UNTRIM\'MED</b>, <i>a.</i> Not trimmed; not pruned; not dressed; not put in order.',
  },
  'Untriumphable': {
    'id': 58155,
    'definition': '<b>UNTRI\'UMPHABLE</b>, <i>a.</i> That admits no triumph. [Barbarous and not used.]',
  },
  'Untriumphed': {
    'id': 58156,
    'definition': '<b>UNTRI\'UMPHED</b>, <i>a.</i> Not triumphed over.',
  },
  'Untrod': {
    'id': 58157,
    'definition': '<b>UNTROD\'<br><br>UNTROD\'DEN</b>, <i>a.</i> Not having been trod; not passed over; not marked by the feet.',
  },
  'Untrolled': {
    'id': 58158,
    'definition': '<b>UNTROLLED</b>, <i>a.</i> Not boiled; not rolled along.',
  },
  'Untroubled': {
    'id': 58159,
    'definition': '<b>UNTROUBLED</b>, <i>a.</i> untrub\'led.<br><br>1. Not troubled; not disturbed by care, sorrow or business; free from trouble.<br><br>2. Not agitated; not ruffled; not confused; free from passion; as an untroubled mind.<br><br>3. Not agitated; not moved; as an untroubled lake.<br><br>4. Not disturbed or interrupted in the natural course; as untroubled nature.<br><br>5. Not foul; not turbid; clear; as an untroubled stream.',
  },
  'Untroubledness': {
    'id': 58160,
    'definition': '<b>UNTROUB\'LEDNESS</b>, <i>n.</i> State of being free from trouble; unconcern. [Not used.]',
  },
  'Untrue': {
    'id': 58161,
    'definition': '<b>UNTRUE</b>, <i>a.<br><br></i> 1. Not true; false; contrary to the fact. The story is untrue.<br><br>2. Not faithful to another; not fulfilling the duties of a husband, wife, vassal, &c.; false; disloyal.<br><br>3. Inconstant; as a lover.',
  },
  'Untruly': {
    'id': 58162,
    'definition': '<b>UNTRU\'LY</b>, <i>adv.</i> Not truly; falsely; not according to reality.',
  },
  'Untruss': {
    'id': 58163,
    'definition': '<b>UNTRUSS\'</b>, <i>v.t.</i> To untie or unfasten; to loose from a truss; to let out.',
  },
  'Untrussed': {
    'id': 58164,
    'definition': '<b>UNTRUSS\'ED</b>, <i>a.</i> Not trussed; not tied up.',
  },
  'Untrustiness': {
    'id': 58165,
    'definition': '<b>UNTRUST\'INESS</b>, <i>n.</i> Unfaithfulness in the discharge of a trust.',
  },
  'Untrusty': {
    'id': 58166,
    'definition': '<b>UNTRUST\'Y</b>, <i>a.</i> Not trusty; not worthy of confidence; unfaithful.',
  },
  'Untruth': {
    'id': 58167,
    'definition': '<b>UNTRUTH</b>, <i>n.<br><br></i> 1. Contrariety to truth; falsehood.<br><br>2. Want of veracity.<br><br>3. Treachery; want of fidelity. Obs.<br><br>4. False assertion.<br><br>No untruth can possibly avail the patron and defender long.',
  },
  'Untuckered': {
    'id': 58168,
    'definition': '<b>UNTUCK\'ERED</b>, <i>a.</i> Having no tucker; as an untuckered neck.',
  },
  'Untunable': {
    'id': 58169,
    'definition': '<b>UNTU\'NABLE</b>, <i>a.<br><br></i> 1. Not harmonious; not musical.<br><br>2. Not capable of making music.<br><br>3. Not capable of being tuned or brought to the proper pitch.',
  },
  'Untune': {
    'id': 58170,
    'definition': '<b>UNTU\'NE</b>, <i>v.t.<br><br></i> 1. To make incapable of harmony.<br><br>Untune that string.<br><br>2. To disorder.<br><br>Untun\'d and jarring senses.',
  },
  'Unturned': {
    'id': 58171,
    'definition': '<b>UNTURN\'ED</b>, <i>a.</i> Not turned. He left no stone unturned.',
  },
  'Untutored': {
    'id': 58172,
    'definition': '<b>UNTU\'TORED</b>, <i>a.</i> Uninstructed; untaught; as untutored infancy.',
  },
  'Untwine': {
    'id': 58173,
    'definition': '<b>UNTWI\'NE</b>, <i>v.t.<br><br></i> 1. To untwist.<br><br>2. To open; to disentangle.<br><br>3. To separate, as that which winds or clasps.',
  },
  'Untwist': {
    'id': 58174,
    'definition': '<b>UNTWIST\'</b>, <i>v.t.<br><br></i> 1. To separate and open, as threads twisted; or to turn back that which is twisted.<br><br>2. To open; to disentangle; as intricacy.',
  },
