  'Wadsett': {
    'id': 59441,
    'definition': '<b>WADSETT</b>, <i>n.</i> An ancient tenure or lease of land in the highlands of Scotland, which seems to have been a kind of mortgage.',
  },
  'Wadsetter': {
    'id': 59442,
    'definition': '<b>WADSETTER</b>, <i>n.</i> One who holds by wadsett.',
