  'Wafter': {
    'id': 59447,
    'definition': '<b>WAFTER</b>, <i>n.</i><br><br>1. He or that which wafts; a passage boat.<br><br>2. The conductor of vessels at sea; an old word.',
  },
  'Wafting': {
    'id': 59448,
    'definition': '<b>WAFTING</b>, <i>ppr.</i> Carrying through a bouyant medium.',
