  'Waits': {
    'id': 59492,
    'definition': '<b>WAITS</b>, <i>n.</i><br><br>1. Itinerant nocturnal musicians. [Not in use.]<br><br>2. Nocturnal musicians who attended great men.',
  },
  'Waive': {
    'id': 59493,
    'definition': '<b>WAIVE</b>, <i>n.</i> A woman put out of the protection of the law.',
