  'Water-Carriage': {
    'id': 59726,
    'definition': '<b>WATER-CARRIAGE</b>, <i>n.</i> [water and carriage.]<br><br>1. Transportation or conveyance by water; or the means of transporting by water.<br><br>2. A vessel or boat. [Not in use.]',
  },
  'Water-Cart': {
    'id': 59727,
