  'Water-Wheel': {
    'id': 59795,
    'definition': '<b>WATER-WHEEL</b>, <i>n.</i> [water and wheel.]<br><br>1. A wheel moved by water.<br><br>2. An engine for raising water from a deep well.',
  },
  'Water-Willow': {
