  'Wayward': {
    'id': 59860,
    'definition': '<b>WAYWARD</b>, <i>a.</i> [way and ward.] Froward; peevish; perverse; liking his own way.<br><br>Wayward beauty doth not fancy move.',
  },
  'Waywardly': {
    'id': 59861,
    'definition': '<b>WAYWARDLY</b>, <i>adv.</i> Frowardly; perversely.',
