  'Weld': {
    'id': 60005,
    'definition': '<b>WELD, WOLD</b>, <i>n.</i> A plant of the genus Reseda, used by dyers to give a yellow color, and sometimes called dyers weed. It is much cultivated in Kent for the London dyers.<br><br><b>WELD</b>, <i>v.t.</i> To wield.<br><br><b>WELD</b>, <i>v.t.</i> [G., to join.] To unite or hammer into firm union, as two pieces of iron, when heated almost to fusion.',
  },
  'Welded': {
    'id': 60006,
    'definition': '<b>WELDED</b>, <i>pp.</i> Forged or beat into union in an intense heat.',
  },
  'Welder': {
    'id': 60007,
    'definition': '<b>WELDER</b>, <i>n.</i><br><br>1. One who welds iron.<br><br>2. A manager; an actual occupant. [Not in use.]',
  },
  'Welding': {
    'id': 60008,
    'definition': '<b>WELDING</b>, <i>ppr.</i> Uniting in an intense heat.',
