  'Wiredrawing': {
    'id': 60557,
    'definition': '<b>WIREDRAWING</b>, <i>ppr.</i><br><br>1. Drawing a metal into wire.<br><br>2. Drawing to a great length or fineness.',
  },
  'Wiredrawn': {
    'id': 60558,
    'definition': '<b>WIREDRAWN</b>, <i>pp.</i> Drawn into wire; drawn out to great length or fineness.',
